import type { Snapshot } from "./contracts";
import type { QuestionKind } from "@/generated/prisma/client";
type Question = { id: string; kind: QuestionKind; difficulty: "EASY" | "MEDIUM" | "HARD"; topic: string; snapshot: Snapshot };
const question = (id: string, kind: QuestionKind, topic: string, title: string, statement: string, reference: string): Question => ({ id, kind, topic, difficulty: "EASY", snapshot: { version: 1, title, statement, details: "Explain your reasoning, discuss costs or tradeoffs, and give a concrete check or example.", reference, revision: null, slug: null } });
const ask = (id: string, kind: QuestionKind, difficulty: Question["difficulty"], topic: string, title: string, statement: string, reference: string): Question => ({ ...question(id, kind, topic, title, statement, reference), difficulty });
export const INTERVIEW_QUESTIONS: Question[] = [
  question("collection-membership", "CONCEPTUAL", "hash-maps", "Workshop Check-In Index", "A workshop checks whether each arriving badge ID is on a registration list. Compare scanning the list for every arrival with building a hash set once. Explain duplicate IDs, expected time, worst-case qualifications and extra memory.", "A list scan costs O(n) per arrival, or O(nm) for m arrivals. Building a hash set takes expected O(n) time and O(n) extra memory; m membership checks take expected O(m). Duplicates collapse if only membership matters. Hash performance depends on the implementation and collisions; expected constant time is not a universal worst-case guarantee. Test registered, missing and repeated IDs."),
  question("last-crate", "DEBUGGING", "arrays", "The Missing Final Crate", "A depot counts positive crate weights using: let count = 0; for (let i = 0; i < weights.length - 1; i++) { if (weights[i] > 0) count++; } return count; Find the defect, propose the smallest correction, and describe tests that would catch it.", "The loop excludes the last index. Use i < weights.length. With [4] the faulty loop returns 0 instead of 1; [0, 3] isolates a positive final element. Also test [], all nonpositive values and multiple positives. A full scan costs O(n) time and O(1) extra space."),
  question("repeated-ledger", "OPTIMIZATION", "arrays", "Repeated Depot Totals", "An immutable ledger has n signed changes. A service answers q half-open range-sum requests by scanning each requested range. Propose a faster design for many requests, explain its cost, and describe what changes if ledger entries can be edited frequently.", "Use n+1 prefix totals with prefix[0]=0; answer [a,b) with prefix[b]-prefix[a]. Preprocessing takes O(n), each query O(1), and extra memory O(n), for O(n+q) total. Frequent point updates make rebuilding expensive; discuss a Fenwick tree or segment tree with O(log n) update/query costs. Check empty ranges, negative values and an end equal to n."),
  question("handoff-decision", "BEHAVIORAL", "design", "A Handoff Under Pressure", "A teammate asks you to merge a feature shortly before a demo, but you find an untested failure case. Describe how you would communicate the issue, decide what to ship, and follow up. Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Describe the situation and your responsibility, then the specific risk and evidence. Offer proportionate choices such as a fix with a focused check, a reduced demo scope or a rollback plan. Explain whom you involve, how you avoid blame, and how you document the decision. Conclude with the outcome or expected outcome and a follow-up improvement. Do not invent a personal achievement."),
  question("study-room-booking", "SYSTEM_DESIGN", "design", "Campus Study Room Booking", "Sketch a small campus room-booking service. Students browse availability and reserve one room for a time interval. Explain the data model, how you prevent overlapping reservations during concurrent requests, and how you handle retries. Start with one campus rather than global scale.", "Clarify interval boundaries, cancellations and identity. Model rooms, users and bookings; validate times and authorization on the server. A database exclusion constraint on room/time ranges, or a transaction with appropriate locking, prevents concurrent overlaps; an availability check alone is insufficient. Use an idempotency key for retries. Index lookup paths, return conflicts clearly and test two competing reservations, touching intervals and canceled bookings."),
  // Expanded bank: at least three original prompts for every non-coding style at every difficulty.
  ask("stack-or-queue", "CONCEPTUAL", "EASY", "stack", "Undo History and Print Jobs", "An editor needs an undo history, and an office needs a print queue. Choose a stack or a queue for each, explain the order each one serves items in, and give the cost of adding and removing an item.", "Undo must reverse the most recent action first, so it is last-in first-out: a stack, with O(1) push and pop at the top. Print jobs should run in arrival order, first-in first-out: a queue, with O(1) enqueue at the back and dequeue at the front (a linked list, ring buffer or two-stack queue; Array.shift is O(n) in JavaScript). Mention redo as a second stack that is cleared on a new edit, and test undo after redo and an empty queue."),
  ask("index-or-walk", "CONCEPTUAL", "EASY", "arrays", "Seat Lookup by Position", "A theater stores seats either in an array or in a singly linked list. Compare reading the 500th seat, inserting a seat at the front, and inserting at the end for each structure, and say which you would pick for frequent position lookups.", "An array reads any index in O(1) because elements are contiguous; a linked list must walk 499 links, O(n). Inserting at the front is O(n) for an array (shifting) but O(1) for a list. Appending is amortized O(1) for a dynamic array and O(1) for a list only if it keeps a tail pointer. For frequent position lookups choose the array. Arrays also have better cache locality. Check index 0, the last index and an empty structure."),
  ask("hash-collisions", "CONCEPTUAL", "MEDIUM", "hash-maps", "When Two Keys Share a Bucket", "Explain how a hash table stores two keys that hash to the same bucket. Describe chaining and open addressing, what the load factor is, and why resizing keeps operations fast on average even though a single resize is expensive.", "Chaining keeps a small list (or tree) per bucket; open addressing probes for another free slot (linear or quadratic probing, double hashing) and needs tombstones for deletes. Load factor = entries / buckets; as it grows, chains or probe sequences lengthen. Doubling the bucket array when the load factor passes a threshold rehashes all n entries in O(n), but doublings are geometrically spaced, so the cost averages to O(1) per insert (amortized). Worst case is still O(n) per lookup with adversarial or poor hashes. Test colliding keys, deletes followed by lookups, and growth across a resize."),
  ask("bfs-or-dfs", "CONCEPTUAL", "MEDIUM", "graphs", "Choosing a Traversal", "For a maze given as a grid, compare breadth-first and depth-first search for (a) checking whether the exit is reachable and (b) finding the fewest moves to the exit. Discuss memory use and what changes if moves had different costs.", "Both detect reachability in O(V + E). BFS explores in order of distance, so in an unweighted maze the first time it reaches the exit is a shortest path; DFS may find a long path first. BFS stores a frontier that can be as wide as the maze (O(V) worst case); recursive DFS uses stack depth up to O(V) and can overflow, so an explicit stack is safer. With different move costs, plain BFS is no longer correct: use Dijkstra's algorithm (non-negative costs) or 0-1 BFS for costs of 0 and 1. Test a start equal to the exit, an unreachable exit and a maze with several routes of different lengths."),
  ask("sql-join-kinds", "CONCEPTUAL", "MEDIUM", "sql", "Students Without Enrollments", "Tables students(id, name) and enrollments(student_id, course_id) are given. Explain the difference between INNER JOIN and LEFT JOIN here, write a query that lists every student with their number of courses (including zero), and explain why COUNT(*) would be wrong.", "INNER JOIN keeps only students with at least one enrollment; LEFT JOIN keeps every student and fills enrollment columns with NULL when there is no match. Query: SELECT s.id, s.name, COUNT(e.course_id) AS courses FROM students s LEFT JOIN enrollments e ON e.student_id = s.id GROUP BY s.id, s.name. COUNT(*) counts rows, and the NULL-padded row would count as 1 for a student with no courses; COUNT(e.course_id) ignores NULLs and gives 0. Filtering enrollments in WHERE would turn the LEFT JOIN back into an inner join, so put such filters in the ON clause. Test a student with zero, one and several enrollments, and duplicate enrollments."),
  ask("amortized-growth", "CONCEPTUAL", "HARD", "arrays", "Why Doubling Beats Adding Ten", "A dynamic array grows when full. Compare growing by a constant (add 10 slots) with growing by a factor (double the capacity). Derive the total copying cost of n appends for each, and explain what 'amortized O(1)' does and does not promise.", "Adding 10 slots copies about 10 + 20 + ... + n elements, roughly n²/20, so appends are O(n) amortized. Doubling copies 1 + 2 + 4 + ... + n < 2n elements in total, so each append is O(1) amortized. Amortized means the average over any sequence is bounded; a single append can still cost O(n) during a resize, which matters for latency-sensitive code. Any factor greater than 1 gives O(1) amortized; smaller factors (like 1.5) waste less memory but copy more often. Shrinking needs hysteresis (for example shrink at one-quarter full) to avoid resize thrashing. Check the costs with a small simulation of 1, 2, 4 and 8 elements."),
  ask("greedy-or-dp", "CONCEPTUAL", "HARD", "dynamic-programming", "When Greedy Is Safe", "For making change with the fewest coins, the rule 'always take the largest coin that fits' works for some coin systems but not others. Explain why, give a counterexample, and describe how you would decide between a greedy algorithm and dynamic programming for a new problem.", "Greedy is correct only if a locally best choice can always be extended to a global optimum, which is usually shown with an exchange argument. With coins {1, 3, 4} and amount 6, greedy takes 4 + 1 + 1 (three coins) but 3 + 3 uses two. Dynamic programming over amounts (best[a] = 1 + min best[a - c]) is correct for any system in O(amount × coins). To decide: try to prove the greedy choice property (or find a small counterexample by brute force), check for optimal substructure, and fall back to DP when overlapping subproblems exist. Test with brute force on small amounts."),
  ask("sql-index-order", "CONCEPTUAL", "HARD", "sql", "Composite Index Column Order", "A table orders(customer_id, created_at, status, total) has frequent queries filtering by customer_id and sorting by created_at, and occasional queries filtering only by status. Propose indexes, explain why column order in a composite index matters, and name situations where an index exists but the database will not use it.", "A composite B-tree index on (customer_id, created_at) serves WHERE customer_id = ? ORDER BY created_at directly: equality on the leading column, then range or order on the next. The reverse order cannot narrow by customer first. An index on status alone may be ignored when status has few distinct values (low selectivity); a partial index (WHERE status = 'PENDING') can help. Indexes go unused when the query wraps the column in a function (WHERE date(created_at) = ...), uses a leading wildcard LIKE '%x', compares mismatched types, or when the planner estimates a full scan is cheaper. Every index slows writes and costs storage. Verify with EXPLAIN on realistic data."),
  ask("binary-search-loop", "DEBUGGING", "EASY", "binary-search", "The Search That Never Ends", "A function finds the first index whose value is at least target: let lo = 0, hi = arr.length; while (lo < hi) { const mid = Math.floor((lo + hi) / 2); if (arr[mid] < target) lo = mid; else hi = mid; } return lo; It sometimes never returns. Find the defect, fix it, and give tests that would have caught it.", "When arr[mid] < target the loop sets lo = mid, but mid can equal lo (for example lo = 0, hi = 1), so the interval never shrinks. The fix is lo = mid + 1, because mid is known to be too small. With hi = mid in the other branch the interval [lo, hi) always shrinks and the loop ends with lo == hi as the answer. Tests: [1] with target 2 (the original loops forever), [1, 3] with target 3, an empty array, a target smaller than everything and duplicates of the target."),
  ask("shared-roster", "DEBUGGING", "EASY", "object-oriented", "Two Teams, One Roster", "class Team { static players = []; add(name) { Team.players.push(name); } list() { return Team.players; } } const red = new Team(); const blue = new Team(); red.add('Ana'); blue.list() returns ['Ana']. Explain the bug, fix it, and describe a test that proves teams are independent.", "players is a static field, so it belongs to the class and is shared by every instance. Each team should own its own list: declare an instance field (players = [];) or assign this.players = [] in the constructor, and use this.players in add and list. Returning the internal array also lets callers mutate it; return a copy ([...this.players]) to protect the invariant. Test: add to red only, then check blue.list() is empty, and check that mutating a returned list does not change the team."),
  ask("remove-while-iterating", "DEBUGGING", "MEDIUM", "arrays", "Skipped Expired Coupons", "Code removes expired coupons: for (let i = 0; i < coupons.length; i++) { if (coupons[i].expired) coupons.splice(i, 1); } Two adjacent expired coupons are not both removed. Explain why and give two correct fixes with their costs.", "splice shifts later elements left, so the coupon that moves into position i is never checked before i increments. Fixes: iterate backwards (for i from length - 1 down to 0), so shifts only affect already-visited indices; or build a new array with filter((c) => !c.expired), which is O(n) instead of O(n²) for many splices and avoids mutation. If mutation in place is required, use a write index to compact in one pass. Test two and three adjacent expired coupons, an all-expired list, a list with none expired and an empty list."),
  ask("loop-closure", "DEBUGGING", "MEDIUM", "design", "Every Reminder Says Five", "for (var i = 0; i < 5; i++) { setTimeout(() => console.log('reminder', i), 100); } prints 'reminder 5' five times instead of 0 through 4. Explain the cause and give two fixes.", "var is function-scoped, so all five callbacks close over the same variable, which equals 5 by the time the timers fire. Fix by using let, which creates a new binding per iteration, or pass the value explicitly (an IIFE, or setTimeout's extra arguments: setTimeout((n) => log(n), 100, i)). Explain the event loop: the timers run only after the loop finishes. Test by collecting the logged values and asserting [0, 1, 2, 3, 4]."),
  ask("sql-null-filter", "DEBUGGING", "MEDIUM", "sql", "The Missing Unassigned Tickets", "SELECT COUNT(*) FROM tickets WHERE assignee <> 'sam' is meant to count tickets not assigned to Sam, but unassigned tickets (assignee IS NULL) are missing from the count. Explain why, fix the query, and name a second NULL pitfall in aggregates.", "Comparisons with NULL yield UNKNOWN, not TRUE, so WHERE assignee <> 'sam' drops rows where assignee is NULL. Fix: WHERE assignee <> 'sam' OR assignee IS NULL, or WHERE assignee IS DISTINCT FROM 'sam' where supported. A related pitfall: COUNT(column) and AVG(column) ignore NULLs while COUNT(*) does not, and NOT IN (subquery) returns no rows if the subquery contains a NULL; prefer NOT EXISTS. Test with rows for Sam, another person and NULL."),
  ask("lost-update", "DEBUGGING", "HARD", "system-design", "Overselling the Last Ticket", "A checkout handler does: row = SELECT stock FROM items WHERE id = ?; if (row.stock > 0) UPDATE items SET stock = ? WHERE id = ? (with row.stock - 1). Under load, more tickets are sold than were in stock. Explain the race, propose fixes in the database, and describe how you would reproduce it in a test.", "Two requests can both read stock = 1, both pass the check, and both write 0: a lost update, because read-check-write is not atomic. Fixes: a single conditional statement (UPDATE items SET stock = stock - 1 WHERE id = ? AND stock > 0, then check the affected row count); SELECT ... FOR UPDATE inside a transaction to lock the row; or optimistic concurrency with a version column and retry. Add a CHECK (stock >= 0) constraint as a backstop. Make the operation idempotent so client retries do not double-charge. Reproduce with two concurrent transactions against a real database (or a barrier in the test) and assert exactly one succeeds."),
  ask("deep-recursion", "DEBUGGING", "HARD", "trees", "The Crash on Long Chains", "A recursive function computes the depth of a tree: depth(node) = node ? 1 + Math.max(depth(node.left), depth(node.right)) : 0. It works in tests but crashes with 'Maximum call stack size exceeded' on production data where some trees are long chains of 200,000 nodes. Explain the failure and rewrite it to be safe, keeping the same result.", "Each recursive call uses a stack frame, and a degenerate tree (a chain) recurses once per node, exceeding the engine's stack limit. Rewrite iteratively: a breadth-first traversal counting layers, or an explicit stack of [node, depth] pairs tracking the maximum. Both are O(n) time; memory becomes O(width) or O(height) on the heap instead of the call stack. Tests: an empty tree, a single node, a balanced tree, and generated left-only and right-only chains of 200,000 nodes."),
  ask("negative-edge", "DEBUGGING", "HARD", "graphs", "A Refund That Breaks Routing", "A route planner uses Dijkstra's algorithm. After adding a 'refund' leg with negative cost, it reports a total that is higher than a route a user found by hand. Explain why Dijkstra's algorithm gives the wrong answer, and what you would use instead and when that alternative itself fails.", "Dijkstra finalizes a node when it is popped, assuming no later path can be cheaper; with a negative edge, a node reached later through that edge can become cheaper after it was finalized. Use Bellman-Ford (relax all edges V - 1 times, O(VE)), which handles negative edges and detects negative cycles with one more pass; if a negative cycle is reachable, the shortest cost is undefined. For DAGs, relaxing in topological order also works in O(V + E). Alternatively, model refunds outside path cost. Test a small graph where the negative edge changes the answer, and one with a negative cycle."),
  ask("set-membership", "OPTIMIZATION", "EASY", "hash-maps", "Checking Banned Usernames", "A sign-up check runs bannedList.includes(name) for each of m new names, and bannedList has n entries. Explain the cost, propose a faster approach, and mention what you would need to keep in mind about case and whitespace.", "includes scans the array, so m checks cost O(n·m). Build a Set once in O(n) and each lookup is expected O(1), for O(n + m) overall, with O(n) extra memory. Normalize the same way on both sides (trim, lowercase, Unicode normalization) before inserting and looking up, or variants slip through. If the list changes, update the set rather than rebuilding it per request. Test an exact match, a case variant, surrounding spaces and an empty list."),
  ask("string-building", "OPTIMIZATION", "EASY", "strings", "Building a Long Report", "A report is built with report = report + line + '\\n' inside a loop over 100,000 lines. Explain why this can be slow in some languages, propose a faster pattern, and say how you would measure the difference.", "If strings are immutable and concatenation copies, each append copies the whole report so far, which is O(n²) total characters. Collect lines in an array and join once (lines.join('\\n')), or use a string builder, which is O(total length). Some JavaScript engines optimize repeated + with ropes, so measure rather than assume: time both versions on realistic sizes and check memory. Also consider streaming lines to the output instead of holding the whole report."),
  ask("n-plus-one", "OPTIMIZATION", "MEDIUM", "sql", "Slow Order History Page", "An order history page loads 50 orders with one query, then runs one query per order to fetch its items, so the page makes 51 queries. Explain the problem, propose two fixes, and discuss the tradeoffs of each.", "This is the N+1 query pattern: per-row round trips dominate latency and database load. Fix with a JOIN (one query returning orders with items, then group in code; duplicates order columns per item) or with a batched second query (SELECT * FROM items WHERE order_id IN (...)) and group by order_id, which keeps result sets narrow. ORMs expose this as eager loading or include. Index items(order_id). Measure query count and latency before and after; test orders with zero items and many items."),
  ask("stream-top-k", "OPTIMIZATION", "MEDIUM", "heaps", "Top Ten Slowest Requests", "A dashboard finds the ten slowest requests among 50 million log lines by loading all durations into an array and sorting it. Propose a better approach, give its time and memory, and explain how it changes if the logs arrive as a stream.", "Sorting needs O(n log n) time and O(n) memory. Keep a min-heap of size 10: push each duration, and when the heap exceeds 10 pop the smallest; the heap then holds the ten largest. That is O(n log k) time and O(k) memory, and it works on a stream because each line is processed once. Quickselect is O(n) average but needs all data in memory. Mention ties and sorting the final ten for display. Test fewer than ten lines and many equal durations."),
  ask("memoize-paths", "OPTIMIZATION", "MEDIUM", "dynamic-programming", "A Grid Counter That Times Out", "countPaths(r, c) returns countPaths(r - 1, c) + countPaths(r, c - 1), with base cases at the edges, to count right/down routes in a grid. It is instant for 10 × 10 but hangs for 30 × 30. Explain why, and make it fast without changing the recurrence.", "The recursion recomputes the same cells exponentially many times (the call tree has about C(r + c, r) leaves). Memoize results by (r, c) in a map or 2D array so each cell is computed once: O(r × c) time and memory. Or fill a table bottom-up, and since each row only needs the previous row, reduce memory to O(c). The count grows quickly, so use BigInt or a modulus if required. Test 1 × 1, 1 × n, a 30 × 30 grid and compare with the closed form C(r + c - 2, r - 1)."),
  ask("cache-hot-endpoint", "OPTIMIZATION", "HARD", "system-design", "A Leaderboard Under Load", "A public leaderboard endpoint recomputes rankings from the database on every request and slows down during events with thousands of requests per second. Propose a caching strategy, including where the cache lives, how entries expire or are invalidated, and how you prevent a stampede when an entry expires.", "Compute the ranking once and serve it from a cache: an in-memory or shared cache (such as Redis) keyed by board and page, plus HTTP caching with a short max-age for public pages. Choose freshness explicitly: a TTL of a few seconds, or invalidate or update on score writes (or maintain the ranking incrementally in a sorted structure). Prevent a stampede with request coalescing (one recomputation while others wait), stale-while-revalidate, or jittered TTLs. Never cache per-user private data under a shared key. Measure hit rate, p95 latency and database load before and after, and load-test the expiry moment."),
  ask("keyset-pagination", "OPTIMIZATION", "HARD", "sql", "Deep Pages Are Slow", "An API lists activity with ORDER BY created_at DESC LIMIT 20 OFFSET n. Page 1 is fast but page 5,000 takes seconds, and users sometimes see duplicates when new activity arrives. Explain both problems and redesign the pagination.", "OFFSET makes the database read and discard n rows, so deep pages cost O(n). Inserts between requests shift rows, so items repeat or are skipped. Use keyset (cursor) pagination: return the last (created_at, id) seen and query WHERE (created_at, id) < (?, ?) ORDER BY created_at DESC, id DESC LIMIT 20, with an index on (created_at, id). The id tie-breaker makes the order total. Each page is then O(log n + page size) and stable under inserts. The tradeoff is that you cannot jump to an arbitrary page number. Test equal timestamps, inserts between pages and the last page."),
  ask("bitset-dedupe", "OPTIMIZATION", "HARD", "bit-manipulation", "Deduplicating Ten Million IDs", "A batch job must find duplicate IDs among 10 million integers in the range 0 to 99,999,999. A hash set runs out of memory on the worker. Propose a memory-efficient approach, estimate its memory, and discuss when it would not apply.", "Use a bitset with one bit per possible ID: 100,000,000 bits is about 12.5 MB, versus hundreds of MB for a hash set of boxed integers. For each ID, test bit (id >> 3, id & 7) in a Uint8Array (or 32-bit words); if it is set the ID is a duplicate, otherwise set it. O(n) time, O(range) memory. It needs a known, dense, bounded range; for sparse or huge ranges use sorting (external sort if needed), partitioning by hash into files, or a Bloom filter when false positives are acceptable. Test the smallest and largest IDs and repeated IDs."),
  ask("learning-fast", "BEHAVIORAL", "EASY", "design", "Learning Something New Quickly", "Describe a time you had to learn an unfamiliar tool, language or library quickly to finish a task. Explain how you approached learning it, how you checked your understanding, and what you would do differently. Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer names the situation and deadline, then shows a deliberate approach: reading official documentation first, building a tiny working example, comparing it with existing code in the project, and asking a knowledgeable person targeted questions. It shows how understanding was verified (tests, a review, a small demo), states the result honestly, and reflects on one concrete improvement. Avoid vague claims and do not invent results; quantify only what you can support."),
  ask("asking-for-help", "BEHAVIORAL", "EASY", "design", "Knowing When to Ask", "Tell me about a time you were stuck on a problem. How long did you try on your own, how did you decide to ask for help, and how did you make it easy for the other person to help you? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Describe the problem and what you tried, with evidence (error messages, a minimal reproduction, hypotheses ruled out). Explain a reasonable timebox before asking and why, then how you framed the question: the goal, what you expected, what happened and what you already tried. Show what you learned and how you shared it (notes or documentation) so others would not get stuck the same way. Balance independence against wasting team time, and give credit to the helper."),
  ask("design-disagreement", "BEHAVIORAL", "MEDIUM", "design", "Disagreeing About an Approach", "Describe a time you disagreed with a teammate about a technical approach. How did you present your view, how did you evaluate theirs, and how was the decision made? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Explain the context and both positions fairly, including the strongest version of the other person's argument. Show how you moved from opinion to evidence: criteria agreed up front (correctness, complexity, timeline, maintenance), a quick prototype or measurement, or input from an owner. Describe how the decision was made and how you supported it even if it was not your proposal. Mention the outcome and what you learned about collaboration. Avoid framing the teammate as wrong or yourself as the hero."),
  ask("slipping-deadline", "BEHAVIORAL", "MEDIUM", "design", "A Deadline You Were Going to Miss", "Tell me about a time you realized partway through that you would not finish on time. When did you notice, whom did you tell, and what options did you offer? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Strong answers show early detection (tracking progress against milestones, noticing scope growth) and early, specific communication to the people affected, with options rather than just bad news: reduce scope, move the date, add help, or ship a partial version behind a flag. Explain the tradeoffs of each and the decision taken. Close with the outcome and a process change, such as breaking work smaller or estimating with buffers. Do not blame others or hide the slip."),
  ask("tough-review", "BEHAVIORAL", "MEDIUM", "design", "Critical Code Review Feedback", "Describe a time you received critical feedback on your code or design. How did you respond in the moment, what did you change, and how did it affect your later work? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Describe the feedback concretely and your initial reaction honestly. Show that you separated the work from yourself: asking clarifying questions, understanding the reasoning, and either making the change or explaining a different view with evidence. Give the concrete change and how you applied the lesson later (a checklist item, a test habit, a pattern you now use). Show appreciation for the reviewer. Avoid answers where the feedback was simply wrong or where you only complied without understanding."),
  ask("incident-response", "BEHAVIORAL", "HARD", "system-design", "Handling a Production Incident", "Describe a time something you worked on broke for real users. Walk through how you detected it, how you limited the damage, how you found the cause, and what you changed afterwards. Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Cover detection (alerts, user reports, monitoring), immediate mitigation before root cause (rollback, feature flag, disabling the path), and clear communication with status updates to stakeholders. Then show methodical diagnosis: logs, metrics, a timeline, a reproduction and a confirmed root cause rather than a guess. Describe the fix and the blameless follow-up: a regression test, better alerts, safer deploys and a written postmortem with owners and dates. Quantify impact only if you know it. Avoid blaming individuals."),
  ask("ambiguous-request", "BEHAVIORAL", "HARD", "design", "Clarifying an Ambiguous Project", "Tell me about a project where the requirements were unclear or kept changing. How did you decide what to build first, how did you reduce uncertainty, and how did you keep stakeholders aligned? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Show how you turned ambiguity into explicit questions and assumptions, wrote them down, and confirmed them with the people who owned the outcome. Describe building the smallest useful slice first (a prototype or vertical slice) to get feedback early, defining measurable success criteria, and making changes cheap (modular design, feature flags). Explain how you communicated tradeoffs when requirements changed and how you avoided silent scope creep. End with the result and what you would repeat."),
  ask("debt-tradeoff", "BEHAVIORAL", "HARD", "design", "Shipping With Known Shortcuts", "Describe a time you chose to ship something with a known shortcut or technical debt to meet a goal. How did you decide it was acceptable, how did you contain the risk, and what happened to the debt later? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer makes the tradeoff explicit: the business value of shipping now versus the risk and future cost. It shows guardrails, such as tests around the risky part, monitoring, a feature flag or a limited rollout, and recording the debt with a ticket and an owner. It describes whether and how the debt was repaid, or why it was consciously kept. Reflect on how you would judge a similar decision now. Avoid presenting shortcuts as free or as someone else's problem."),
  ask("short-links", "SYSTEM_DESIGN", "EASY", "system-design", "A Small Link Shortener", "Design a service that turns long URLs into short codes like /k3x9 and redirects visitors. Start with one server and a database. Explain how codes are generated, what is stored, what happens on a redirect, and how you would avoid two links getting the same code.", "Store rows (code primary key, long_url, created_at, owner). Generate codes from a database sequence encoded in base 62 (short, unique, but guessable), or random 7-character codes with a unique constraint and retry on collision. Validate URLs and block unsafe schemes. Redirect with a 301 (cacheable) or 302 (if analytics or edits matter), looking up by primary key. Add rate limiting on creation, and a cache for hot codes. Unique constraints, not application checks, prevent duplicate codes under concurrency. Test unknown codes, collisions and invalid URLs."),
  ask("library-loans", "SYSTEM_DESIGN", "EASY", "object-oriented", "Modeling Library Loans", "Design the classes for a small library app: members borrow copies of books, each copy can be on loan to at most one member, and members may have at most three loans. Name the classes, their key fields and methods, and where each rule is enforced.", "Separate Book (title, author, isbn) from Copy (id, book, status), because many copies share one book. Member has id, name and its active loans; Loan links a copy and a member with due and returned dates. A Library (or LoanService) owns checkout(member, copy) and return(copy), enforcing the rules in one place: the copy must be available and the member must have fewer than three active loans. checkout creates a Loan and marks the copy on loan atomically. Keep fields private and expose intention-revealing methods instead of setters. In a database, a unique constraint on active loans per copy backs the rule. Test the fourth loan, double checkout and returns."),
  ask("parking-garage", "SYSTEM_DESIGN", "EASY", "object-oriented", "A Parking Garage Model", "Design classes for a parking garage with several levels and spot sizes (motorcycle, compact, large). Vehicles get the smallest suitable free spot, receive a ticket, and pay by duration when leaving. Describe the classes, how a spot is chosen, and how you would add a new vehicle type later.", "Classes: Garage (levels and pricing), Level (spots), Spot (id, size, occupied by), Vehicle (with a size, or subclasses), Ticket (spot, entry time) and a Pricing policy. Spot choice: keep free spots per size (sets or queues) and search from the vehicle's size upward. Assign and free spots in one place so the occupied state stays consistent. Pricing is a strategy object so rules can change without touching the rest. Adding a vehicle type means adding a size mapping, not editing every class (open/closed principle). Test a full garage, a size fallback and fee rounding."),
  ask("distributed-rate-limit", "SYSTEM_DESIGN", "MEDIUM", "system-design", "Rate Limiting Across Servers", "An API runs on many servers behind a load balancer. Design a rate limiter allowing each API key 100 requests per minute. Compare a few algorithms, explain where the counters live, and what happens when that store is slow or down.", "Algorithms: fixed window (simple, allows bursts at boundaries), sliding log (exact, memory-heavy), sliding-window counter (approximate, cheap) and token bucket (smooth, allows controlled bursts). Per-server memory is not enough behind a load balancer, so keep counters in a shared low-latency store (such as Redis) with an atomic increment-and-expire or a script, keyed by API key and window. Return 429 with Retry-After and rate-limit headers. If the store is unavailable, choose fail-open (availability) or fail-closed (protection) per endpoint, possibly with a local fallback limit. Watch clock skew and hot keys. Test boundary bursts and many keys."),
  ask("notification-service", "SYSTEM_DESIGN", "MEDIUM", "system-design", "Sending Notifications Reliably", "Design a service that sends email and push notifications when events happen in an app, such as 'your order shipped'. Explain how events reach the service, how failures and retries work, and how you avoid sending the same notification twice.", "Producers publish events to a durable queue (or an outbox table written in the same transaction as the business change) so events are not lost if the app crashes. Workers consume, render templates, check user preferences and call providers. Retries use exponential backoff with jitter, and repeatedly failing messages go to a dead-letter queue for inspection. Queues deliver at least once, so a worker may process the same event twice, and no local record alone can make an external send exactly-once: if the worker crashes before calling the provider the send is lost unless the job is retried, and if the provider call times out after accepting the message a retry may send a duplicate. Keep durable delivery state per (event, channel, user) (pending, sent, failed) and pass a stable idempotency key derived from it to providers that support one, so the provider deduplicates retries. Where a provider has no such support, accept that a timed-out send is ambiguous: decide whether a rare duplicate or a rare miss is worse for that notification type, and reconcile using provider delivery reports or webhooks. Rate-limit per user and per provider. Test provider timeouts, crashes between the state write and the send, duplicate events and a user who has opted out."),
  ask("enrollment-api", "SYSTEM_DESIGN", "MEDIUM", "sql", "Course Enrollment With Seat Limits", "Design the data model and API for course enrollment where each course has a seat limit, students can join a waitlist, and a seat freed by a drop goes to the first waitlisted student. Explain the tables, constraints and transactions that keep counts correct under concurrent requests.", "Tables: courses(id, capacity), enrollments(course_id, student_id, status ENROLLED or WAITLISTED, created_at) with a unique (course_id, student_id). Enrolling runs in a transaction that locks the course row (SELECT ... FOR UPDATE) or uses a conditional update on a seats_taken counter, then inserts ENROLLED if a seat is free, otherwise WAITLISTED. Dropping deletes or updates the enrollment and, in the same transaction, promotes the earliest WAITLISTED row (ORDER BY created_at, id LIMIT 1 FOR UPDATE SKIP LOCKED). Constraints, not only code, guard invariants. Make the API idempotent for retries. Test two students racing for the last seat and drops with an empty waitlist."),
  ask("chat-delivery", "SYSTEM_DESIGN", "HARD", "system-design", "Messages in a Group Chat", "Design the backend for group chat: users send messages to rooms, members online receive them in real time, and members who were offline see the history in order when they return. Discuss message ordering, storage, fan-out to online users and what happens when a client retries a send.", "Clients keep persistent connections (WebSocket) to gateway servers; a presence map records which gateway holds each user. A send goes to a message service that assigns a per-room sequence number (ordering within a room, not globally), stores the message, then fans out through a pub/sub channel per room to the gateways with online members. Offline members fetch history by room and sequence (WHERE room_id = ? AND seq > last_seen ORDER BY seq). A client-generated message ID with a unique constraint makes retries idempotent. Partition storage by room. For very large rooms, fan out on read instead of write. Test reconnects, duplicate sends and out-of-order arrival."),
  ask("live-leaderboard", "SYSTEM_DESIGN", "HARD", "system-design", "A Real-Time Leaderboard", "Design a leaderboard for a game with millions of players where scores change constantly, players want their own rank, and the top 100 must update within seconds. Discuss data structures, storage, how ranks are computed, and how the design scales.", "Keep a sorted structure per board (such as a Redis sorted set): updating a score is O(log n), the top 100 is a range read, and a player's rank is O(log n). The database stays the source of truth, with the sorted set rebuilt from it if lost. Batch or debounce writes during spikes, and validate scores server-side against cheating. For scale, shard by board or region. For a global rank across shards, use per-shard counts of higher scores, or approximate ranks with score buckets for the long tail while keeping exact ranks for the top. Cache the top 100 for a second or two. Test ties (break them by earlier achievement time), score decreases and shard failover."),
  ask("upload-pipeline", "SYSTEM_DESIGN", "HARD", "system-design", "Large File Uploads", "Design how users upload files of up to 2 GB that must be virus-scanned and turned into previews before others can see them. Explain how the bytes travel, how processing happens, how users see progress, and how you handle failures halfway through.", "Avoid streaming large files through app servers: the API authorizes the upload and returns a pre-signed URL (multipart, resumable) for direct upload to object storage. A completion callback or storage event creates a record in state PENDING and enqueues a job. Workers scan, generate previews and set the state to READY or REJECTED; files are not served until READY, and quarantined objects stay private. Jobs are idempotent and retried with backoff, and failures land in a dead-letter queue. Users see progress from the client during upload and from the record's state afterwards (polling or push). Enforce size and type limits, expire abandoned multipart uploads, and test interrupted uploads, duplicate completion events and an infected file."),
  // Second expansion: at least five original prompts for every non-coding style at every difficulty.
  ask("recursion-call-stack", "CONCEPTUAL", "EASY", "recursion", "What a Recursive Call Costs", "A function sumDigits(n) returns the sum of the decimal digits of a non-negative integer by calling itself on Math.floor(n / 10). Explain what the base case is, what the call stack looks like for sumDigits(493), how much extra memory it uses compared with a loop, and why a missing base case is a problem.", "The base case is n < 10, which returns n without another call. Every recursive call must move toward it, here by dropping the last digit. For sumDigits(493) the calls nest as 3 + sumDigits(49), then 9 + sumDigits(4); the third call hits the base case and returns 4, and each earlier frame adds its digit as it is popped. With d digits the recursion keeps d frames on the stack, so extra space is O(d) against O(1) for a loop, while time is O(d) either way. Without a base case, or with one the arguments never reach, calls keep nesting until the runtime throws a stack overflow error. Here the depth equals the digit count, at most about 309 for a JavaScript Number, so stack depth is not a practical risk for this function; the same recursive shape over a long linked list or a deep tree could nest hundreds of thousands of levels, and there a loop or an explicit stack is safer. A different limit applies to the input itself: Number.MAX_SAFE_INTEGER is 2^53 - 1 (9007199254740991). Integers above that boundary are not all exactly representable as Numbers, so digit arithmetic may already start from a rounded input. Accept only safe integers, or use BigInt or a digit string for larger exact inputs. Test 0, a single digit, a number containing zeros such as 1005, a value just above Number.MAX_SAFE_INTEGER, and a negative input if you decide to accept one."),
  ask("sort-then-scan", "CONCEPTUAL", "EASY", "sorting", "Why Sort Before Scanning", "A clerk has n recorded arrival times, in seconds, for a loading dock and must find the smallest gap between any two arrivals. Compare checking every pair with sorting the times and scanning neighbours. Explain why only adjacent values in sorted order need to be compared, give the time and extra memory of each approach, say why a hash set does not help here, and say what changes if the times arrive already sorted.", "Checking every pair costs O(n^2) time and O(1) extra space. Sorting costs O(n log n) comparisons, then one O(n) pass takes the minimum of a[i+1] - a[i]; extra space depends on the sort, O(1) beyond the array for an in-place sort such as heapsort and O(n) for a merge sort or a library sort that works on a copy. Sorting in place also reorders the caller's data, so copy first if the original order matters. Only neighbours need comparing because for sorted values a <= b <= c the gap c - a is at least b - a, so any non-adjacent pair is beaten by a pair of neighbours between them; the minimum gap always occurs between adjacent values. A hash set answers exact-equality questions, so it can detect a gap of zero (a duplicate) but cannot find the nearest value, because closeness depends on order rather than equality. If the input is already sorted, skip the sort and the whole task is one O(n) pass. Test fewer than two arrivals (define the result or reject), exactly two, duplicates (gap 0), unsorted and negative-offset inputs, and compare against the pairwise version on random small arrays."),
  ask("priority-queue-choices", "CONCEPTUAL", "MEDIUM", "heaps", "Three Ways to Keep a Priority Queue", "A hospital triage screen repeatedly adds patients with an urgency score and removes the most urgent one. Compare an unsorted array, an array kept sorted, and a binary heap on insertion and on removing the most urgent patient. Also say how long it takes to build the structure from n patients already waiting, and name something a heap does not do well.", "With an unsorted array, insertion is O(1) at the end but removing the most urgent needs a scan, O(n). With a sorted array (most urgent at the end), removal is O(1) but insertion must shift elements, O(n), even though binary search finds the position in O(log n). A binary heap stored in an array makes both insertion and removal O(log n) by sifting up or down along a tree of height about log2 n, and peeking at the top is O(1). Building a heap from n existing items with bottom-up heapify is O(n), which beats n separate insertions at O(n log n) in the worst case. A heap is poor at searching for an arbitrary item (O(n)), at ordered traversal, and at changing a priority by value unless you also track each item's position, in which case an update is O(log n). Equal scores are not served in arrival order unless you add a sequence number as a tiebreaker. Test equal scores, an empty queue and interleaved inserts and removals."),
  ask("sql-having-vs-where", "CONCEPTUAL", "MEDIUM", "sql", "Big Spenders This Year", "Tables customers(id, name) and orders(id, customer_id, total, ordered_at) are given. Write a query that lists each customer's name and total spend for orders placed in 2025, only for customers whose 2025 spend exceeds 500. Explain the difference between WHERE and HAVING and why the condition on the sum cannot go in WHERE.", "SELECT c.name, SUM(o.total) AS spend FROM customers c JOIN orders o ON o.customer_id = c.id WHERE o.ordered_at >= DATE '2025-01-01' AND o.ordered_at < DATE '2026-01-01' GROUP BY c.id, c.name HAVING SUM(o.total) > 500 ORDER BY spend DESC. WHERE filters individual rows before they are grouped; HAVING filters whole groups after aggregation, so only HAVING can use SUM. A half-open date range keeps orders late on 31 December that BETWEEN '2025-01-01' AND '2025-12-31' would drop for timestamp columns, and it can use an index on ordered_at; if ordered_at is timestamptz the year boundaries follow the session time zone, so decide which zone defines the year. Group by the primary key as well as the name so two customers who share a name are not merged. The inner join drops customers with no orders, which is correct here because their spend cannot exceed 500, and SUM ignores NULL totals. Test a customer at exactly 500 (excluded), one whose orders are all in 2024, one with an order at 23:30 on 31 December 2025, and two customers with the same name."),
  ask("isolation-write-skew", "CONCEPTUAL", "HARD", "sql", "What Isolation Levels Actually Prevent", "Two on-call doctors each run a transaction that counts the doctors currently on call and, if more than one, marks themselves off call. Both run at the same time and nobody is left on call. Name this anomaly, explain which PostgreSQL isolation levels allow it, and describe two ways to prevent it.", "This is write skew: each transaction reads a set of rows, decides from what it saw, and writes a different row, so there is no write-write conflict and neither overwrites the other. In PostgreSQL both READ COMMITTED (the default) and REPEATABLE READ (snapshot isolation) permit it, because each transaction sees a state in which two doctors are on call. SERIALIZABLE uses serializable snapshot isolation, which detects the dangerous read/write pattern and aborts one transaction with a serialization failure (SQLSTATE 40001); the application must retry the whole transaction, so the transaction body must be safe to repeat and free of external side effects. Alternatives that work at lower levels: lock the rows the decision depends on, for example SELECT id FROM doctors WHERE on_call ORDER BY id FOR UPDATE, so the second transaction waits and then re-evaluates the rows after the first commits (under REPEATABLE READ it would instead fail with a serialization error and need a retry); or make the rows conflict by also updating a shared row such as a per-ward counter, or enforce the invariant in a place the database can check atomically. Test with two concurrent sessions and a deliberate pause between the read and the write; do not rely on timing luck."),
  ask("union-find-cost", "CONCEPTUAL", "HARD", "union-find", "Why Union-Find Is Nearly Constant", "A union-find structure tracks the connected groups of a network as links are added. Explain how union by size and path compression work, what each contributes, and what the claim 'nearly constant time' means precisely. Describe one problem it solves well and one it cannot solve.", "Each element stores a parent pointer and the root represents its set. find follows parents to the root; with path compression it also repoints the visited nodes closer to (or directly at) the root, flattening the tree for later calls. Union by size attaches the smaller tree under the larger root, which keeps trees shallow: with union by size alone a find is O(log n). With both techniques, any sequence of m operations on n elements takes O(m alpha(n)) total time, where alpha is the inverse Ackermann function, which grows so slowly that it stays below 5 for any input that fits in a computer. That is an amortized bound over a sequence, not a per-operation guarantee, so one find can still walk a long path. It suits connectivity when links are only added: counting components as edges arrive, detecting the edge that closes a cycle in an undirected graph, and Kruskal's minimum spanning tree. It cannot delete a link or split a set, cannot handle directed reachability, and cannot return the path between two nodes, only whether they are connected. Write find iteratively to avoid deep recursion, and test repeated unions, self-unions and a long chain."),
  ask("palindrome-end", "DEBUGGING", "EASY", "strings", "A Palindrome Check That Rejects Everything", "function isPalindrome(s) { let i = 0, j = s.length; while (i < j) { if (s[i] !== s[j]) return false; i++; j--; } return true; } It returns false for 'level'. Find the defect, fix it, and say why a single test for the empty string would not have caught it.", "j starts at s.length, one past the last valid index, so s[j] is undefined and the first comparison fails for every non-empty string. Start with j = s.length - 1. After the fix, 'level' and 'a' return true and 'ab' returns false. The empty string passes both the broken and the fixed versions because the loop body never runs, so a test suite containing only '' gives false confidence. Good tests cover an odd-length palindrome, an even-length palindrome such as 'abba', a one-character string, a non-palindrome that differs only in the middle, and one that differs only at the ends. Ignoring case or punctuation is a separate requirement that should be handled by normalizing the string before the loop."),
  ask("default-sort-order", "DEBUGGING", "EASY", "sorting", "Scores Sorted in the Wrong Order", "const scores = [10, 9, 100, 1]; scores.sort(); console.log(scores); prints [1, 10, 100, 9] instead of [1, 9, 10, 100]. Explain why, fix it, and describe a side effect of sort that callers often overlook.", "Without a comparator, Array.prototype.sort converts the elements to strings and compares them by UTF-16 code units, so '10' and '100' sort before '9'. Pass a comparator that returns a negative, zero or positive number: scores.sort((a, b) => a - b). Returning a boolean such as a > b is wrong because false and true convert to 0 and 1, never to a negative number. The subtraction is fine for ordinary finite numbers, but NaN or Infinity values need explicit handling. sort also sorts the array in place and returns that same array, so the original order is lost; copy first with [...scores].sort(...), or use toSorted where the runtime supports it. Test mixed digit counts, negative numbers, duplicates, an empty array, and assert that the input is unchanged when a copy is expected."),
  ask("bracket-counter", "DEBUGGING", "MEDIUM", "stack", "Brackets That Balance Only by Count", "function balanced(s) { let open = 0; for (const ch of s) { if ('([{'.includes(ch)) open++; else if (')]}'.includes(ch)) open--; } return open === 0; } It returns true for '([)]' and for ')('. Explain why, fix it, and list the tests you would write.", "Counting only checks that the number of opening brackets equals the number of closing ones. It ignores which type closes which opener and whether a closer ever appears before its opener, so ')(' ends at zero even though the count went negative along the way. Use a stack: push each opener; on a closer, fail if the stack is empty or if the popped opener is not the matching type; at the end the stack must be empty. That is O(n) time and O(n) space in the worst case. Test '', '()', '([{}])', '(]', '([)]', ')(', '((' and '))', and a string with non-bracket characters mixed in, which should be ignored."),
  ask("window-jumps-back", "DEBUGGING", "MEDIUM", "sliding-window", "The Window That Jumped Backwards", "let start = 0, best = 0; const last = {}; for (let i = 0; i < s.length; i++) { const c = s[i]; if (c in last) start = last[c] + 1; last[c] = i; best = Math.max(best, i - start + 1); } return best; is meant to return the length of the longest substring without repeated characters, but it returns 3 for 'abba' where the answer is 2. Find the defect and fix it.", "When a character reappears, its previous position may lie to the left of start, outside the current window. Setting start = last[c] + 1 then moves the left edge backwards and lets a repeated character back in. For 'abba': at i = 2 the second 'b' moves start to 2, but at i = 3 the earlier 'a' (index 0) moves start back to 1, so the window 'bba' of length 3 contains a duplicate. Fix with start = Math.max(start, last[c] + 1). The left edge must never move left, which is the invariant that makes the scan O(n). Test 'abba', 'tmmzuxt' (answer 5), 'abcabcbb' (answer 3), a string of one repeated character, and the empty string."),
  ask("foreach-not-awaited", "DEBUGGING", "MEDIUM", "design", "Done Before It Is Done", "items.forEach(async (item) => { await save(item); }); console.log('all saved'); prints 'all saved' immediately, and when one save fails the error surfaces as an unhandled rejection instead of reaching the surrounding try/catch. Explain why and give corrected versions with their tradeoffs.", "forEach ignores the promises returned by its callback, so it does not wait for any of them: the callbacks start, forEach returns, and the log runs before the saves finish. A rejection inside a callback has no awaiting caller, so a try/catch around forEach cannot catch it. To run saves one after another use for (const item of items) { await save(item); }, which keeps order and stops at the first failure but is slower. To run them concurrently use await Promise.all(items.map(save)); it starts every save at once, which can overload the backend, and it rejects as soon as one fails without cancelling the others. Use Promise.allSettled to collect every outcome, or process in limited batches to cap concurrency. Test with a mocked save that has delays and one rejecting item, and assert both when completion is reported and that the error reaches the caller."),
  ask("split-the-cents", "DEBUGGING", "HARD", "math", "The Penny That Vanished", "A bill of 100.00 is split evenly among 3 people with const share = Math.round((total / 3) * 100) / 100; and every person is charged share. The charges add up to 99.99 and a reviewer notices the missing cent. Explain why it happens and design a correct split, including how you would represent the money.", "100 / 3 is 33.333..., which rounds to 33.33, and three of those add up to 99.99. Rounding each share independently does not preserve the total. Separately, binary floating point cannot represent most decimal fractions exactly (0.1 + 0.2 is 0.30000000000000004 in JavaScript), so store money as integer minor units such as 10000 cents or in an exact decimal type, and round only at the edges. Split in integers: base = Math.floor(totalCents / n) and extra = totalCents % n, then give one extra cent to each of the first extra people, producing 3334, 3333 and 3333, which sum exactly. Document a deterministic rule for who receives the extra cent, such as sorted participant ID, and for weighted splits use the largest-remainder method. Use each currency's own number of minor-unit digits rather than assuming two. Test totals that do not divide evenly, a total smaller than the number of people, zero, negative refunds, and assert that the shares always sum to the total."),
  ask("transfer-deadlock", "DEBUGGING", "HARD", "sql", "Two Transfers, One Deadlock", "A transfer runs in one transaction: UPDATE accounts SET balance = balance - 50 WHERE id = $from, then UPDATE accounts SET balance = balance + 50 WHERE id = $to. Occasionally, when Ana sends to Ben at the same moment Ben sends to Ana, one request fails with a deadlock error. Explain the cause, how the database reacts, and two ways to prevent or handle it.", "Each transaction locks the sender's row first and then waits for the receiver's row, so one holds Ana and wants Ben while the other holds Ben and wants Ana: a circular wait. PostgreSQL's deadlock detector notices it after deadlock_timeout (one second by default), aborts one transaction with SQLSTATE 40P01 and lets the other finish. To prevent it, acquire locks in a consistent global order: lock both rows up front with SELECT id FROM accounts WHERE id IN ($from, $to) ORDER BY id FOR UPDATE and only then run the two updates, so both transfers lock the lower id first. To handle what remains, retry the whole transaction on 40P01 (and 40001) a bounded number of times with a short randomized delay, and keep transactions short. Guard against overdrafts in the same statement, for example UPDATE ... SET balance = balance - 50 WHERE id = $from AND balance >= 50, and check the affected row count. Reproduce with two connections that transfer in opposite directions in a loop, and assert that both complete and the total balance is unchanged."),
  ask("budget-pair-scan", "OPTIMIZATION", "EASY", "two-pointers", "Two Gifts That Fit the Budget", "A sorted array holds gift prices, and a shopper wants exactly two gifts whose prices add up to the budget. The current code tries every pair with two nested loops. Propose a faster approach that uses the sorted order, give its cost, and explain why it never skips a valid pair.", "The nested loops cost O(n^2). With the array sorted, keep one pointer at each end. Compute the sum of the two values: if it equals the budget, report the pair; if it is too small, move the left pointer right; if it is too large, move the right pointer left. When the sum is too small, the left value cannot pair with anything at or before the right pointer, because the right value is the largest remaining candidate, so discarding it loses no valid pair; the too-large case is symmetric. Each step discards one element, so the scan is O(n) time and O(1) space. Stop when the pointers meet so an item is never paired with itself. If the input is not sorted, sorting first costs O(n log n), and a hash set gives O(n) expected time with O(n) memory. Test no valid pair, a pair at the two ends, duplicate values that sum to the budget, and fewer than two items."),
  ask("length-in-loop", "OPTIMIZATION", "EASY", "linked-list", "A Length Call Inside the Loop", "A report routine prints every item of a singly linked list with for (let i = 0; i < list.length(); i++) print(list.get(i)). Both length() and get(i) walk from the head. A timing run shows 2 ms for 1,000 items, 200 ms for 10,000 and 20 seconds for 100,000. Say what that growth pattern tells you, how you would locate the hidden cost without guessing, and how you would fix it.", "A tenfold larger input taking about a hundredfold longer is the signature of quadratic work. To find the cause, count node visits with an instrumented list or use a profiler rather than guessing: the loop condition calls length() n + 1 times at n visits each, and get(i) walks i links, so the total is roughly 1.5 n^2 visits. Hoisting length() before the loop (valid only if the list is not modified inside it) removes about two thirds of that work but leaves get(i) at O(n^2) overall, so it is only a partial fix. Rewrite as a single traversal, for (let node = list.head; node !== null; node = node.next) print(node.value), which is O(n) time and O(1) extra space. Keep a size field updated on every insert and delete if callers need length() often, and expose an iterator so callers do not walk the structure by index. Verify by re-running the timings, which should now scale roughly tenfold per tenfold of input, and by asserting about n visits on the instrumented list. Test an empty list, one item and a list of 100,000 nodes."),
  ask("best-sales-stretch", "OPTIMIZATION", "MEDIUM", "sliding-window", "Longest Stretch Within Budget", "Daily sales are non-negative numbers in an array of n values. A report wants the longest run of consecutive days whose total stays at or below a budget B. The current code tries every start day and end day and re-adds the days in between with an inner loop. Make it faster, give the cost before and after, explain why your method is valid, and list the edge cases you would test.", "Trying every start and end and re-adding the days costs O(n^3); keeping a running total per start brings it to O(n^2). Because the values are non-negative, use a variable-size window with two pointers: extend the right end one day at a time, adding its value, and while the total exceeds B advance the left end, subtracting the values that leave, then record the window length. Each index enters and leaves the window once, so time is O(n) and extra space O(1). It is valid because of non-negativity: if the days from l to r exceed B, every window that starts at or before l and ends at r also exceeds B, so the left end never needs to move backwards. With negative values that argument fails and the window can need to grow again after shrinking; use prefix sums with an ordered structure or a different approach instead, or reject negatives. Edge cases: n = 0, B below zero (answer 0, no valid stretch), a single day above B (the window shrinks to empty), zeros in the data, B = 0 with zero-sales days, every day fitting (answer n), ties between equally long stretches (decide which to report), and floating-point drift when adding and subtracting decimals, which integer cents avoid. Check the result against the O(n^2) version on random small arrays."),
  ask("lower-email-lookup", "OPTIMIZATION", "MEDIUM", "sql", "Case-Insensitive Login Lookups", "A users table has a unique index on email, yet the login query SELECT * FROM users WHERE lower(email) = lower($1) takes seconds on 5 million rows. Explain why the index is not used and give two fixes with their tradeoffs.", "The index stores email values, but the condition compares lower(email), a different expression, so the planner cannot use the plain index and scans the table. Fix 1: an expression index, CREATE INDEX users_email_lower_idx ON users (lower(email)); queries must use the same expression, and making it UNIQUE also enforces case-insensitive uniqueness, though creation fails if existing rows differ only in case, so check for such duplicates first. On a live table use CREATE INDEX CONCURRENTLY, which cannot run inside a transaction block. Fix 2: normalize on write (store lowercase, with a CHECK (email = lower(email))) and look up by plain equality on the existing index, which needs a backfill and every writer to follow the rule; the citext type is a related option. Tradeoffs: an extra index costs storage and write time, and lower() depends on the collation, so non-ASCII text can behave differently. Whether addresses are treated as case-insensitive is a product decision. Verify with EXPLAIN that the new plan uses an index scan, and test mixed-case input."),
  ask("bulk-row-import", "OPTIMIZATION", "HARD", "sql", "Loading Two Million Rows", "A nightly job loads 2 million rows into events(id, device_id, reading, taken_at) by sending one INSERT per row, each in its own transaction, and takes hours. Propose faster approaches, say where the time is going, and explain how you keep the load safe to re-run after a failure.", "Per row you pay a network round trip, statement parsing and planning, a commit that waits for the write-ahead log to be flushed, and index maintenance; the round trips and commits dominate. Group many rows per transaction (batches of a few thousand) so commits are amortized; send many rows per statement with a multi-row INSERT ... VALUES or INSERT ... SELECT FROM unnest($1::bigint[], $2::int[], ...); or use COPY, PostgreSQL's bulk-load path, through the driver's copy API or psql \\copy. By default COPY aborts the whole load on the first bad row. PostgreSQL 17 adds COPY ... (ON_ERROR ignore), which skips rows that fail input conversion, such as text in an integer column, and reports how many were skipped; constraint violations (duplicate keys, NOT NULL, CHECK) still abort the load, and skipped rows must be counted and reviewed rather than silently lost. The common pattern therefore still holds: COPY into a temporary staging table, validate it, then INSERT ... SELECT into the real table. On an initially empty table, creating secondary indexes after the load is usually faster than maintaining them row by row; on a live table that trick does not apply. Relaxing durability settings can speed commits but risks losing recent commits after a crash, so agree on that risk before using it. For safe re-runs, key rows by a natural or batch-derived ID and use INSERT ... ON CONFLICT (id) DO NOTHING (or DO UPDATE if later data should win), and record batch progress so a retry resumes. Measure with a 100,000-row sample before and after instead of guessing."),
  ask("typeahead-prefix", "OPTIMIZATION", "HARD", "tries", "Typeahead Over Two Million Titles", "A search box shows the first ten product titles that start with what the user has typed. The roughly 2 million titles sit in an array and change a few times an hour; each keystroke runs titles.filter((t) => t.toLowerCase().startsWith(prefix)).slice(0, 10). Propose a faster design, compare at least two data structures on time, memory and update cost, and say what else you would do.", "The current code does work proportional to the number of titles times their length per keystroke, and it lowercases every title each time. Normalize titles once (case, accents, whitespace). Option A: a sorted array of normalized titles; two binary searches find the contiguous range that starts with the prefix in O(L log N), and you read ten entries, but they come out alphabetically unless you rank them. Option B: a trie, or a compressed radix tree, where each node keeps its top-ten titles by popularity, so a query is O(L) after walking the prefix; the cost is memory for nodes and precomputed lists, and an insert must update the lists along its path. Because updates are only a few per hour, rebuilding the index periodically and swapping it in atomically is simple and safe. Option C: delegate to a search engine's prefix query. Beyond the structure: debounce keystrokes, cancel stale requests, cache hot short prefixes, require a minimum prefix length, and handle ties. Test an empty prefix, a prefix with no matches, ranking ties and accented input, and measure memory on realistic data rather than assuming it."),
  ask("explain-to-outsider", "BEHAVIORAL", "EASY", "design", "Explaining a Technical Idea Simply", "Tell me about a time you explained a technical concept or decision to someone without that background. Who was the audience, how did you adapt your explanation, and how did you check that they understood? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer names the audience and what they needed to decide or do, then shows adaptation: starting from their goals rather than the mechanism, replacing jargon with an accurate everyday comparison or a small concrete example, and leaving out detail that did not matter to them. It shows how understanding was checked, for example asking them to restate the idea or predict an outcome, and how the explanation changed when they were confused. Report the result honestly, such as a decision made or a mistake avoided, and name one thing to improve. Avoid blaming the listener, over-simplifying until it is wrong, or claiming results you cannot support."),
  ask("owning-small-mistake", "BEHAVIORAL", "EASY", "design", "Owning a Small Mistake", "Describe a small mistake you made in your work or studies, such as a wrong assumption or a skipped step. How did you find out, whom did you tell and when, and what did you change so it would be less likely to happen again? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Choose a genuine, modest mistake and describe it plainly without minimizing it. Show how it was discovered (a test, a review, your own check) and that you told the affected people promptly rather than hoping nobody noticed, including what was impacted and what you were doing about it. Then show the fix and one lasting change, such as a checklist item, an automated test or a question you now ask earlier. Strong answers take responsibility without self-blame, keep the focus on learning, and do not invent consequences. A hypothetical answer must be labeled as such and still be concrete."),
  ask("plan-changed-midway", "BEHAVIORAL", "MEDIUM", "design", "When the Plan Changed Midway", "Tell me about a time priorities changed after you had already started work. How did you decide what to do with the work in progress, whom did you consult, and how did you handle the cost of switching? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Describe the original goal and what changed, then how you responded: confirming the new priority and its deadline with the person who set it, listing what was done and what was not, and deciding whether to finish, pause or discard the work in progress by comparing the remaining benefits with future costs, rather than letting effort already spent drive the decision. Show how you communicated the effect on other commitments and on teammates who depended on you, and how you left the paused work in a state someone could resume (notes, a branch, a ticket). Reflect honestly on what the switch cost and what you would do to make the next change cheaper. Avoid presenting the change as someone else's fault."),
  ask("helping-struggling-peer", "BEHAVIORAL", "MEDIUM", "design", "Helping a Struggling Teammate", "Describe a time you helped a teammate or classmate who was struggling with a task. How did you notice, how did you offer help without taking over, and how did you know it worked? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer shows how you noticed (missed check-ins, repeated questions, a stalled branch) and how you approached the person privately and respectfully, asking what was blocking them before suggesting anything. It describes helping them build the skill instead of doing the work for them: pairing, asking guiding questions, pointing to the right documentation, or breaking the task into smaller steps. It says how you balanced this against your own commitments and how success was judged, such as the person completing a later task unaided, without inventing numbers. Include what you learned about teaching or communication. Avoid portraying the teammate as incompetent."),
  ask("pushing-back-risk", "BEHAVIORAL", "HARD", "design", "Pushing Back on a Risky Request", "Tell me about a time you believed a deadline, scope or technical decision handed to you was risky and you said so. How did you gather evidence, what alternatives did you propose, and what did you do once the decision was made, whether or not it went your way? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Strong answers show that the concern was backed by evidence (an estimate, a measurement, an incident history, a list of unknowns) and raised early, privately or in the right forum, with respect for the decision maker's context. They offer options rather than only objections: a smaller scope, a phased rollout, a spike to reduce uncertainty, or an explicit risk acceptance. Once a decision is made, show how you committed to it, or escalated appropriately if there was a serious safety or integrity issue, and how you recorded the risks and watched for them. Be honest about the outcome, including when you were wrong or the risk did not materialize. Avoid framing it as winning an argument."),
  ask("failed-project-lessons", "BEHAVIORAL", "HARD", "design", "A Project That Did Not Work Out", "Describe a project or experiment that failed or was cancelled. What did you believe at the start, which warning signs did you see or miss, and which specific habits or practices changed afterwards? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "Pick a real setback and state the original assumptions and goals clearly. Describe the warning signs honestly, including which ones were noticed late, and how decisions were made as they appeared. Separate what was in your control from what was not, and take responsibility for your part without assigning blame to others. The core of the answer is concrete change: earlier validation of the riskiest assumption, smaller milestones, clearer success criteria, a written decision to stop, or better communication with stakeholders, ideally with a later example where the new habit helped. Avoid disguising a success as a failure and avoid claiming lessons you did not act on."),
  ask("classroom-poll", "SYSTEM_DESIGN", "EASY", "system-design", "A Classroom Poll Service", "Design a service where a teacher creates a multiple-choice poll, students vote once from their phones, and the teacher sees live results. Explain the data model, how one vote per student is enforced, how results are shown, and what happens if a student taps twice or a request is retried.", "Tables: polls(id, title, status), options(id, poll_id, label, UNIQUE (poll_id, id)) and votes(poll_id, student_id, option_id, created_at) with PRIMARY KEY (poll_id, student_id), so the database itself enforces one vote per student per poll, plus a composite foreign key (poll_id, option_id) to options(poll_id, id) so a vote cannot name an option from another poll. The vote endpoint authenticates the student, and a single statement such as INSERT INTO votes (poll_id, student_id, option_id) SELECT $1, $2, $3 FROM polls WHERE id = $1 AND status = 'open' ON CONFLICT (poll_id, student_id) DO NOTHING makes a double tap or retry harmless; return the student's recorded vote so the client shows the truth. If changing a vote is allowed, use DO UPDATE instead. Results come from SELECT o.id, o.label, COUNT(v.student_id) FROM options o LEFT JOIN votes v ON v.option_id = o.id AND v.poll_id = o.poll_id WHERE o.poll_id = $1 GROUP BY o.id, o.label, which includes options with zero votes; at classroom scale polling every couple of seconds or server-sent events is enough and no cache is needed. If votes must be anonymous, storing who voted conflicts with that: separating the ballot from a has-voted record reduces linkability but does not remove it, so state that limit. Test a double tap, two concurrent votes from one student, a closed poll and a foreign option."),
  ask("job-claiming", "SYSTEM_DESIGN", "MEDIUM", "system-design", "Claiming Jobs Without Double Runs", "Ten worker processes poll a jobs table for work such as 'send invoice 42'. Design how a worker claims a job so two workers do not run the same one, what happens when a worker crashes in the middle, and which guarantees you can honestly promise.", "Use a jobs table with status, run_at, locked_until and attempts, indexed for the claim query. A worker claims in one statement: WITH next AS (SELECT id FROM jobs WHERE attempts < 5 AND ((status = 'queued' AND run_at <= now()) OR (status = 'running' AND locked_until < now())) ORDER BY run_at, id LIMIT 1 FOR UPDATE SKIP LOCKED) UPDATE jobs SET status = 'running', locked_until = now() + interval '5 minutes', attempts = attempts + 1 FROM next WHERE jobs.id = next.id RETURNING jobs.*. SKIP LOCKED makes concurrent claimers skip rows another transaction has locked instead of waiting, so they receive different jobs. The lease (locked_until) means a crashed worker's job becomes claimable again after it expires. The honest guarantee is therefore at-least-once execution, not exactly-once: a worker can finish the side effect and crash before marking the job done, or run past its lease while another worker takes the job. Make handlers idempotent (pass a stable idempotency key to downstream services, or keep a dedupe record), have the completion update check that the worker still holds the lease, and retry clean failures by setting the job back to queued with a later run_at as backoff. The attempts < 5 predicate (5 is the maximum attempts) stops a poison job that keeps crashing workers from being claimed forever, but it also leaves that job stuck in queued or running, so a periodic sweep should mark jobs with attempts >= 5 that are queued or whose lease has expired as failed for inspection. Test concurrent claimers, a killed worker, an expired lease being re-claimed, a job at the maximum attempts not being claimed, and a handler that outlives its lease."),
  ask("feature-flag-service", "SYSTEM_DESIGN", "MEDIUM", "system-design", "A Feature Flag Service", "Design a service that lets teams turn features on for a percentage of users, for named users, or for everyone, without redeploying. Explain how a user's flag value is computed, how applications learn about changes, and how checks stay fast and safe if the flag service is down.", "Store flags with a key, an enabled switch, a rollout percentage, optional rules or allowlists, a version, and an audit log of who changed what. Evaluate in a fixed order: a disabled kill switch wins, then explicit user overrides, then rules, then the percentage. For the percentage, compute a stable hash of the flag key plus the user ID, take it modulo 100 and compare with the rollout, so a user gets the same answer every time and raising 10 percent to 20 percent only adds users; including the flag key keeps different flags from always selecting the same people. Applications use an SDK that fetches the full configuration at startup and refreshes it by polling (for example every 30 seconds) or by streaming, then evaluates locally in memory, so a check needs no network call. If the service is unreachable, keep serving the last known configuration; if nothing was ever fetched, fall back to safe defaults compiled into the code, normally off for new features. Tradeoffs: changes propagate with a delay and servers can briefly disagree, so evaluate a flag once per request. Add access control, flag expiry and cleanup. Test determinism, monotonic rollout, the distribution over many IDs, and behavior during an outage."),
  ask("ticket-drop-sale", "SYSTEM_DESIGN", "HARD", "system-design", "A Concert Ticket Drop", "Tickets for a popular concert go on sale at noon, and 500,000 people arrive within a minute for 20,000 seats. Design the front door of the sale: how the site absorbs the surge, how people are admitted and ordered, how you limit bots and scalpers, and what happens when a payment times out. Assume per-seat inventory and holds already work correctly; concentrate on traffic, fairness and the payment outcome.", "Put a waiting room in front of checkout. Arrivals get a signed token and a place in line, the waiting page is static and served from a CDN, and admission releases people at a rate the checkout can sustain, measured by checkout latency and error rate rather than guessed. Randomizing the order among people who arrive in the first minutes is more defensible than strict arrival order, which mostly rewards fast connections, but neither is perfectly fair; say so and publish the rule. Bot controls include per-account and per-address rate limits, verification, tokens bound to a session, and a cap on seats per order. Shed load early and cheaply: serve cached availability as a display hint only, return a clear retry response instead of letting requests queue in the application, and degrade non-essential pages first. Hold expiry returns abandoned seats to the pool; the hold itself is the per-seat conditional update covered in other booking designs, so here only note that it must not be a global lock. Payment uses an idempotency key. If the provider times out the outcome is ambiguous, so keep the order pending and reconcile through the provider's status lookup or webhook rather than guessing; define a policy for money captured after a hold expired (honor if the seat is still free, otherwise refund promptly). Test the admission rate, token forgery and reuse, a load test at several times expected traffic, and payment timeouts followed by late webhooks."),
  ask("metrics-pipeline", "SYSTEM_DESIGN", "HARD", "system-design", "A Metrics Collection Pipeline", "Thousands of servers emit CPU and request metrics every 10 seconds. Engineers chart the last day or the last year, and alerts fire when a value crosses a threshold. Design the ingestion path, the storage layout, downsampling and retention, and explain why high-cardinality labels are dangerous.", "Agents batch points and send them to stateless collectors that validate and write to a durable log partitioned by series, so bursts are buffered and consumers can fall behind without losing data. Agent retries mean duplicates, so key each point by (series, timestamp) and make writes idempotent, with last write winning. Storage is a time-series store (purpose-built or columnar) organized by series ID and time block: recent points are held in memory with a write-ahead log, then flushed into immutable compressed blocks, with an index from label sets to series IDs for queries. Keep raw 10-second data for a short period such as days to weeks, and downsample to coarser rollups for long-range charts; store count, sum, min and max per bucket rather than just an average, because averages of averages are wrong when counts differ, and percentiles cannot be recovered from averaged percentiles, so keep histograms or sketches if you need them. Retention drops whole expired blocks cheaply. Alert evaluators query recent data on a schedule and must treat missing data explicitly, since no data is not the same as healthy, and require the condition to hold for a period to avoid flapping. Every distinct label combination is a separate series, so a label like user_id or request_id creates unbounded series; series count, not point count, drives index memory and query cost, so restrict labels to bounded sets and enforce per-tenant series limits. Test duplicate delivery, late and out-of-order points, a collector outage and a label explosion."),
  // Third expansion: at least seven original prompts for every non-coding style at every difficulty.
  ask("who-may-do-what", "CONCEPTUAL", "EASY", "system-design", "Who You Are Versus What You May Do", "A notes app lets a signed-in user open GET /notes/42. A tester changes the 42 to 43 in the address bar and reads another user's note, even though the app correctly checked that the tester was logged in. Explain authentication and authorization, say which one failed, and describe the fix and how you would test it.", "Authentication establishes who the caller is (a session or token tied to a verified login). Authorization decides whether that identity may perform this action on this particular resource. The login check worked, so authentication did not fail; the handler skipped the per-note authorization check, a flaw often called an insecure direct object reference or broken object-level authorization. Fix it on the server, in the data access path: look the note up by id and owner together (WHERE id = $1 AND owner_id = $2, which returned no row for another user's note in a PostgreSQL 17 check), or load it and compare its owner with the authenticated user, and apply the same rule to edit and delete. Answering 404 for notes the caller may not see avoids confirming the id exists; 403 is more explicit but reveals existence, so choose deliberately. Hard-to-guess ids reduce guessing but are not access control, and hiding a link in the interface protects nothing because callers can send any request. Test with two users: the owner gets the note, the other user gets the not-found or forbidden response for read, edit and delete, and an unauthenticated caller is rejected."),
  ask("read-the-loops", "CONCEPTUAL", "EASY", "arrays", "Reading Big-O Off the Loops", "Give the running time in terms of n for each snippet and explain how you counted. (A) for i from 0 to n - 1, for j from i to n - 1, do one step. (B) for (i = 1; i < n; i *= 2) do one step. (C) for i from 0 to n - 1, for (j = 1; j < n; j *= 2) do one step. (D) one loop of n steps followed by a separate loop of m steps. Then say what changes if each step is not constant time.", "(A) The inner loop runs n, n - 1, ..., 1 times, n(n + 1)/2 steps in total, which is O(n^2); the 1/2 and lower-order term are dropped (for n = 1000 the count is 500,500). (B) i doubles each time, so the loop runs about log2 n times: O(log n) (10 iterations for n = 1000). (C) A logarithmic inner loop runs n times: O(n log n) (10,000 steps for n = 1000). (D) Sequential loops add, so O(n + m); keep n and m separate when they are independent inputs. Nested loops multiply, but a fixed inner count such as 5 is a constant, so n iterations of it are still O(n). If each step costs O(k), such as slicing or searching a list, multiply by that cost: n steps that each scan n items are O(n^2). Big-O describes growth, not speed, and ignores constants. Check by counting steps for n and 2n (A should roughly quadruple, B gains one iteration) and test n = 0 and n = 1."),
  ask("test-levels", "CONCEPTUAL", "MEDIUM", "design", "Which Test Catches What", "A checkout feature has a pure function that computes discounts, a repository that saves orders to a database, an HTTP endpoint that ties them together, and a call to an external payment provider. Explain what unit, integration and end-to-end tests would each cover here, which kind you would write most of and why, and how you would test the payment call without charging real cards.", "Unit tests exercise the discount function alone: fast, deterministic and precise about which rule failed, ideal for boundaries such as an empty cart, stacked coupons, rounding and negative totals. Integration tests run real pieces together: the repository against a real database of the same kind as production catches SQL mistakes, constraints, transactions and migrations that a mock hides, and an endpoint test covers validation, authorization and serialization. End-to-end tests drive the deployed interface through a few critical journeys; they find wiring and configuration faults but are slower, more brittle and poor at pointing to a cause, so keep them few. The usual heuristic (the test pyramid) favors many cheap tests and few expensive ones; it is guidance about cost and feedback speed, not a quota, and a data-heavy service may reasonably need more integration tests. Put the provider behind a small interface and use a fake or the provider's sandbox in tests so you can script success, decline, timeout and duplicate responses; a fake cannot prove the real provider behaves the same way, so add a few contract or sandbox checks that run less often. Never use live cards. Keep tests independent: no shared state, a fixed clock and no sleeps. When a bug escapes, add a test at the lowest level that would have caught it."),
  ask("retry-safe-methods", "CONCEPTUAL", "MEDIUM", "system-design", "Which Requests Are Safe to Repeat", "An email says 'Cancel your booking' and links to GET /bookings/7/cancel. Some customers report cancelled bookings they never touched. Separately, a mobile client automatically retries requests that time out. Explain the difference between safe and idempotent HTTP methods, say what is wrong with the cancel link, and classify PUT /users/7 with a full profile, PATCH /counters/7 with {add: 1}, POST /orders and DELETE /orders/7 for automatic retries.", "A safe method (GET, HEAD, OPTIONS) is meant not to change server state, so crawlers, link previewers, prefetchers and email security scanners may fetch such URLs without anyone choosing to; a state-changing GET link can be triggered by software, a plausible cause of the unexplained cancellations. Use a POST or DELETE request from an authenticated page, with a confirmation step and a CSRF defense, rather than a bare link. An idempotent method is one where several identical requests leave the server in the same state as one; PUT and DELETE are defined that way, as are the safe methods. Idempotency describes the effect on state, not the response: a repeated DELETE may return 404 instead of 204. And the handler must really implement it; the method name enforces nothing. PUT /users/7 replaces the whole resource, so a retry is harmless. DELETE /orders/7 is safe to retry. PATCH is not idempotent by definition: setting fields to given values behaves idempotently, but {add: 1} increments again on every retry, so send the new absolute value with a version check or an operation id the server remembers. POST /orders creates a resource each time, so a retry after a lost response can create a duplicate; use a client-generated idempotency key that the server stores with the outcome and returns for repeats within a stated retention period (a widely used convention, not part of HTTP). Test the same request twice, a retry after a lost response, and a link fetched by a scanner."),
  ask("races-without-threads", "CONCEPTUAL", "HARD", "design", "Races Without Threads", "JavaScript runs your code on one thread, yet this account code sometimes overdraws. let balance = 100; async function withdraw(n) { if (balance >= n) { await audit(); balance -= n; } } Two calls to withdraw(80) start together and the balance ends at -60 (audit is any asynchronous call that resolves later). Explain how a race can exist without threads, name the pattern, give fixes with their limits, and explain what changes when the balance lives in a database shared by several servers.", "Only one piece of JavaScript runs at a time, but every await ends the current turn and lets other queued work run. Both calls check balance >= 80 while it is still 100, then each resumes after its await and subtracts, giving 100 - 80 - 80 = -60 (reproduced with a 10 ms timer as audit). This is a check-then-act race: a condition is verified, time passes, and the action assumes it still holds. It is a race condition because the result depends on interleaving; a data race in the strict sense is unsynchronized memory access from different threads, which this is not. Fixes: (1) check and subtract before any await, so no other code can run between them (the second call is then refused and the balance ends at 20), which works only while those two steps stay adjacent; (2) serialize the whole sequence through a promise-chain queue or mutex so one withdrawal runs at a time (also ended at 20), at the cost of throughput, taking care that an exception cannot leave the lock held; (3) re-check after the await and subtract in the same synchronous step, which is correct in one process but runs audit() for withdrawals that are then refused. All of these protect only a single process. With a database shared by several servers use an atomic conditional statement (UPDATE accounts SET balance = balance - 80 WHERE id = $1 AND balance >= 80 and check the affected row count), a row lock inside a transaction, or optimistic versioning with retry. Test by starting both calls together with an artificial delay in the awaited step and asserting the balance never goes negative and exactly one call succeeds."),
  ask("password-storage", "CONCEPTUAL", "HARD", "system-design", "Why Not Just SHA-256 the Password?", "A copy of a login database has leaked. Compare storing passwords as plaintext, as reversibly encrypted text, hashed once with SHA-256, hashed with SHA-256 plus a per-user salt, and hashed with a slow salted password hashing function. Explain what an attacker can do in each case, what the salt and the work factor each contribute, and what hashing still does not protect against.", "Plaintext hands over every password. Reversible encryption is only as safe as its key: the application must be able to decrypt, so an attacker who reaches the app or key store gets everything, and a login system never needs to recover a password. A fast unsalted hash such as SHA-256 is one-way but built to be quick: attackers can test very large numbers of guesses per second on commodity hardware (rates vary widely), can use precomputed tables, and can see that identical passwords have identical hashes. A random per-user salt, stored beside the hash and not secret, defeats precomputed tables and forces each account to be attacked separately, but it does not slow each guess, so weak passwords still fall quickly to a fast salted hash. A password hashing function (Argon2id, scrypt or bcrypt; for example Node's built-in crypto.scrypt with a random salt per user) adds a tunable work factor, plus memory cost for Argon2 and scrypt, which makes every guess expensive for the attacker while costing the defender once per login. Take parameters from current published guidance such as OWASP's, measure on your hardware against an acceptable login delay, and store the algorithm and parameters with each hash so you can raise them and rehash after a successful login. Compare derived bytes with a constant-time function (Node's crypto.timingSafeEqual throws unless the lengths match). An optional pepper kept outside the database helps if only the database leaks but adds key management. Hashing does not stop guessing of weak or reused passwords, phishing, credential stuffing (reused passwords tried against your site) or a compromised running server. Add breached-password checks, rate limiting, multi-factor authentication and a reset flow that does not reveal whether an account exists. Test a correct and a wrong password, two accounts with the same password storing different values, and the upgrade path for old hashes."),
  ask("percent-range-or", "DEBUGGING", "EASY", "math", "A Range Check That Accepts Everything", "A form validator should reject percentages outside 0 to 100: function isValidPercent(x) { return x >= 0 || x <= 100; } Yet isValidPercent(-5) and isValidPercent(150) both return true. Explain why, fix it, and say which inputs still need separate handling.", "With || the result is true when either comparison holds, and every number satisfies at least one: a negative number is <= 100 and a large number is >= 0. So the function returns true for every number except NaN, for which both comparisons are false. A range check needs both bounds to hold, so use &&: x >= 0 && x <= 100. For -5, 50, 150 and NaN the original returns true, true, true, false and the fixed version false, true, false, false. The comparison operators also coerce their operands, so null, true and the string '50' pass even the fixed version (null becomes 0, true becomes 1, '50' becomes 50); if only real numbers are valid, also check typeof x === 'number' and Number.isFinite(x). Decide whether 0 and 100 are inclusive and whether fractions such as 12.5 are allowed. Test -1, 0, 100, 101, a middle value, NaN, Infinity, null, a numeric string and undefined."),
  ask("map-parseint", "DEBUGGING", "EASY", "arrays", "Page Numbers That Turn Into NaN", "A page reads numeric strings with const pages = ['10', '10', '10'].map(parseInt); and expects [10, 10, 10], but console.log(pages) prints [10, NaN, 2]. Explain why, fix it, and compare parseInt with Number for the fix.", "map calls its callback with three arguments (value, index, array), and parseInt takes (string, radix), so the index is passed as the radix. parseInt('10', 0) treats radix 0 as the default and returns 10; parseInt('10', 1) is NaN because 1 is not a valid radix; parseInt('10', 2) parses binary and returns 2. Fix it so only the string is passed and the radix is explicit: .map((s) => parseInt(s, 10)), or use .map(Number). They differ on messy input: Number('12px') is NaN but parseInt('12px', 10) is 12; Number('') is 0 but parseInt('') is NaN; Number('3.9') is 3.9 but parseInt('3.9', 10) is 3. Choose according to whether partial parses should be accepted, and validate the result (Number.isInteger and a range) rather than assuming. Test '10', '', ' 7 ', '12px', '3.9' and ['1', '2', '3'], which the buggy version turns into [1, NaN, NaN]."),
  ask("concatenated-login", "DEBUGGING", "MEDIUM", "system-design", "A Login Query That Trusts Its Input", "A handler builds its query as const sql = `SELECT id FROM users WHERE email = '${email}' AND is_active`; and takes the first row as the logged-in user. A customer whose address is o'brien@example.com gets a database error, and a security tester signs in as someone else by typing x' OR '1'='1 as the email. Explain both failures, fix the code, and say what parameterization does not cover.", "The input is pasted into the SQL text, so it can change the structure of the statement instead of just supplying a value. The apostrophe in o'brien@example.com ends the string literal early and leaves brien@example.com' as invalid SQL, a syntax error (reproduced on PostgreSQL 17). The tester's input produces email = 'x' OR '1'='1' AND is_active; AND binds tighter than OR, so this means email = 'x' OR ('1'='1' AND is_active), true for every active user; a handler that takes the first row then signs the tester in as that user. An input ending in a comment, x' OR 1=1 --, drops the is_active test too and returned inactive users in the same check. Fix it by sending the value separately: db.query('SELECT id FROM users WHERE email = $1 AND is_active', [email]); the server then treats the parameter as data, so quotes in it are ordinary characters. The equivalent PREPARE and EXECUTE statements in a PostgreSQL 17 check returned no row for both attack strings and for the apostrophe address, and found the real user for a valid address (drivers use the protocol's bind step, but the principle is the same). Do not rely on hand-written escaping or blocklists. Parameterization prevents this injection but does not authenticate the caller: do not issue a session from an email lookup alone; verify a credential such as a password hash or a trusted identity-provider assertion first. Parameters can stand in only for values, not table or column names or keywords such as a sort direction, so choose those from an allowlist in code. Also give the application role the least privilege it needs and keep raw database errors out of responses. Test the apostrophe address, ' OR '1'='1, an input ending in --, a trailing semicolon and a legitimate address."),
  ask("dst-plus-24h", "DEBUGGING", "HARD", "math", "Adding 24 Hours Is Not Adding a Day", "A subscription service renews at 09:00 in the customer's local time. The code computes the next renewal with new Date(current.getTime() + 24 * 60 * 60 * 1000), and the server's time zone is America/New_York. After US clocks moved forward in March 2026, a Saturday 09:00 renewal was billed at 10:00 on Sunday, and renewals computed from it stayed at 10:00. The tests pass in CI, whose time zone is UTC. Explain the cause, the autumn counterpart and a design that avoids the problem.", "Adding 24 hours of milliseconds moves the instant exactly 24 hours, but a local calendar day is 23 hours long when clocks go forward and 25 hours when they go back. In America/New_York, Saturday 7 March 2026 09:00 plus 24 hours printed Sunday 8 March 10:00 local, and renewals computed from that value stay at 10:00. In autumn the same arithmetic moved 09:00 on 31 October 2026 to 08:00 on 1 November. With the process time zone set to UTC, which has no daylight saving, 24 hours equals one day, so CI passes while production fails; a developer laptop in another zone may differ again. Fix it with calendar arithmetic in the customer's zone instead of millisecond addition: store the instant in UTC together with the customer's IANA zone name (not a fixed offset), and compute the next local date and time in that zone with a time-zone-aware library or platform API. JavaScript's local-time setDate(getDate() + 1) kept 09:00 in the same test, but it ties the answer to the server's zone, so pass the customer's zone explicitly. Decide and document the policy for local times that do not exist (the skipped hour in spring) or occur twice (the repeated hour in autumn). Run the tests under several fixed zones, for example TZ=America/New_York and TZ=UTC, and include the transition dates. Month-end renewals such as 31 January plus one month need their own rule."),
  ask("leaked-connections", "DEBUGGING", "HARD", "system-design", "Latency Climbing While the Database Looks Idle", "After a release, p99 latency climbs and requests time out, yet database CPU stays low and the app servers are not CPU bound. Dashboards show the connection pool's in-use count pinned at its maximum and a growing queue of waiting requests. The new handler does const client = await pool.connect(); const result = await client.query(sql, [id]); client.release(); return result.rows[0]; Explain the failure, how you would confirm it from metrics and logs before changing code, the fix, and how you would prevent this class of bug.", "If client.query throws (invalid input, a timeout, a constraint violation) the function exits before client.release(), so the connection is never returned. Every failing request permanently removes one connection; once all are leaked, each later request waits in the pool queue and times out although the database is idle, which matches the symptoms. In a simplified stand-in pool of size 2, two failing calls followed by a good call left the third call waiting until a timeout, while the try/finally version served it (this used a stand-in, not a real driver). To confirm before changing code: line up the onset with the release time, check that errors preceded the stall (the first failures are the leaks), graph pool in-use, idle and waiting counts and acquire wait time, compare with the database's own view of its connections (mostly idle and at or below the pool maximum rather than executing queries), and reproduce in staging with a failing query. Mitigate first: roll back or restart (a restart clears leaked connections but they return until the bug is fixed). Fix: try { ... return ... } finally { client.release(); }, or use the pool's own query helper for single statements if your driver provides one, since it acquires and releases for you. A client running a transaction must also roll back on failure before it is released. Prevent it with review or lint rules for acquire and release pairs, an acquire timeout so exhaustion becomes an error and an alert, alerts on pool saturation and wait time, and a test that makes the query fail more times than the pool size and then checks that a later call still succeeds. The same pattern applies to files, locks and timers."),
  ask("some-not-filter", "OPTIMIZATION", "EASY", "arrays", "Work After the Answer Is Known", "A checker asks whether any of 1,000,000 order records is flagged: const hasFlagged = orders.filter((o) => o.flagged).length > 0; In practice the first flagged order is usually near the front. Explain what work is wasted, give a faster equivalent, and say when the two cost the same.", "filter visits every element and builds an array of all matches before its length is read, so it costs O(n) time and up to O(n) extra memory even when the first element qualifies. orders.some((o) => o.flagged) stops at the first match: O(k) time where k is the position of that match, O(1) extra memory, and it scans everything only when nothing matches. On a million numbers with the only match at index 10, filter ran its callback 1,000,000 times and some ran it 11 times. The worst case is the same for both (no match, or a match at the end), so this improves the typical case, not the guaranteed bound. Use find to get the item and findIndex for its position; a for...of loop with an early return is equivalent. If the question is asked repeatedly on changing data, keep a count of flagged records updated on writes instead of scanning each time. Constant factors matter for small arrays, so measure on realistic data. Test an empty array, a match first, a match last and no match."),
  ask("anagram-count", "OPTIMIZATION", "EASY", "strings", "Comparing Many Word Pairs", "A word game must decide, for each of 2 million guess and secret pairs, whether the two words are anagrams. The code sorts the letters of both words and compares the results. The words are usually under ten letters, but a few players submit strings of 100,000 characters. Explain the cost, propose a faster approach and say how much improvement to expect for short and for long inputs.", "Sorting a word of length L costs O(L log L) comparisons, plus allocating arrays and a joined string. Anagrams must have the same length and the same count of each character, so reject different lengths first in O(1), then count: add one for each character of the first word and subtract one for each character of the second, failing if a count would go below zero. That is O(L) time and O(alphabet) space (a Map, or a fixed array of 26 for lowercase a to z). In a test of 100,000 random small cases the counting and sorting versions always agreed. For ten-letter words the gain is only a constant factor, so measure before rewriting; the asymptotic gain matters for the 100,000-character inputs, and the length check rejects most non-anagrams almost immediately. If one secret is compared with many guesses, compute its counts or sorted form once. Define what counts as a letter: case, accents and combining characters (normalize first), and note that iterating a JavaScript string by code point keeps most emoji intact. Test equal words, different lengths, the same letters with different counts ('aab' and 'abb'), the empty string, mixed case and a long input."),
  ask("weight-band-lookup", "OPTIMIZATION", "MEDIUM", "binary-search", "Shipping Rates by Weight Band", "A shipping calculator holds about 20,000 weight bands sorted by their minimum weight, such as 0 g, 500 g and 1,200 g, and finds a parcel's band by scanning from the start until the next band begins above the parcel's weight. At peak it handles thousands of quotes per second per server. Propose a faster lookup, state exactly which boundary your search returns, compare costs, and say when the simple scan is the better choice.", "A scan costs O(B) per quote for B bands. Because the minimum weights are sorted, binary search finds the last band whose minimum is at most the weight in O(log B), at most about 15 steps for 20,000 bands. Define it precisely as 'the index of the last minimum <= w': lo = 0, hi = B; while lo < hi, mid = floor((lo + hi) / 2); if min[mid] <= w then lo = mid + 1, else hi = mid; the answer is lo - 1, and -1 means the weight is below the first band, which should be rejected or handled explicitly. A parcel exactly on a boundary belongs to the band that starts there, which must match the pricing rule (inclusive lower bound, exclusive upper bound). On 20,000 random small tables the binary version matched a linear scan, including weights on a boundary, just below one, above the last band and in an empty table. It requires strictly increasing minimums with no overlaps, which should be validated when the table loads; duplicates make the answer ambiguous. For a few dozen bands the scan is just as fast in practice and simpler, so measure. If rates change rarely, load a sorted table once and swap in a rebuilt copy atomically, and consider caching quotes for repeated weights. Test weights below the first band, exactly at each boundary, just below a boundary, above the last band, a single band and fractional weights."),
  ask("dashboard-latency", "OPTIMIZATION", "MEDIUM", "system-design", "A Dashboard That Takes Two Seconds", "A dashboard endpoint takes about 2 seconds. It awaits a profile service, then the user's orders, then a recommendations service, then renders; each remote call takes about 200 ms in isolation and rendering takes 50 ms. Explain how you would find where the time actually goes, what you would change, and what new risks concurrent calls introduce, including effects on tail latency.", "Measure first: add tracing with one span per downstream call and for the render, inspect a slow request and the percentiles, and compare the time seen by the caller with the time each service reports for itself to separate network, queueing and processing. The stated numbers add up to only about 650 ms, so something else (retries, cold connections, a slow tail, queueing in a saturated pool, a large payload) accounts for the rest and must be found, not guessed. If the three calls are independent, awaiting them one after another adds their latencies, while starting them together with Promise.all makes the wait about the slowest one: in a timer simulation, three 200 ms calls took about 600 ms in sequence and about 200 ms together. Calls that need each other's results must stay sequential. Also drop calls the page does not need, cache slow-changing data, trim payloads, and make non-essential parts such as recommendations optional with a timeout and a fallback (Promise.allSettled or a per-call timeout). Risks: concurrent calls raise instantaneous load on downstream services and on the connection pool; partial failure needs a defined behavior; and a fan-out is as slow as its slowest call, so if each of three calls takes over a second on 1% of requests independently, about 3% of dashboard requests (1 - 0.99^3) will include at least one slow call. Timeouts and budgets therefore matter more at the 99th percentile than at the average. Verify by comparing percentiles before and after on production-like load, and test each dependency failing."),
  ask("precomputed-totals", "OPTIMIZATION", "HARD", "sql", "A Dashboard Total Over Hundreds of Millions of Rows", "An admin dashboard shows orders and revenue per status using SELECT status, count(*), sum(total) FROM orders GROUP BY status over a table that now holds hundreds of millions of rows; the query takes minutes and many admins run it. The figures may be a few minutes out of date. Propose at least two ways to make it fast, with the staleness, locking and write-cost tradeoffs of each, and show the PostgreSQL statements for the one you prefer.", "Reading every row on each view is the problem, so precompute. Option 1, a materialized view: CREATE MATERIALIZED VIEW order_stats AS SELECT status, count(*) AS orders, sum(total) AS revenue FROM orders GROUP BY status; it stores the result and is refreshed on a schedule. A plain REFRESH MATERIALIZED VIEW takes an exclusive lock that blocks readers while it runs (in a two-session test a reader hit a 1 s lock timeout). REFRESH MATERIALIZED VIEW CONCURRENTLY lets readers continue, but it needs an existing unique index on the view with no WHERE clause (CREATE UNIQUE INDEX ON order_stats (status)), fails if the view was created WITH NO DATA and never populated, and is slower because it builds the new result and applies the difference. Either way each refresh recomputes the whole query, a full scan every time, which suits staleness of minutes but not seconds. Option 2, a summary table maintained as orders change (application code or a trigger in the same transaction): reads are instant and current, but every write also updates a summary row, and writers touching the same status queue on that row lock until they commit (in a test a second UPDATE waited about two seconds behind an open transaction). Reduce the hot spot with several counter rows per status that are summed on read, or, for append-only orders, a periodic job that folds in rows after the last processed id. If existing orders can change status or total or be deleted, use a durable change log or CDC stream with compensating deltas instead; an id-only watermark would miss those changes. Whatever you pick: make the refresh schedule explicit, show a 'data as of' time, alert on failed or lagging refreshes, and test by comparing the cached figures with the direct query on a copy, including a refresh while readers query."),
  ask("external-sort", "OPTIMIZATION", "HARD", "sorting", "Sorting More Data Than Fits in Memory", "A nightly job must sort a 40 GB file of log records by timestamp on a machine that can give the sort about 4 GB of memory. Reading everything into an array fails. Design the algorithm, estimate the passes over the data and the CPU cost of the merge, explain how the number of runs and the merge fan-in interact, and list what you would test.", "Use an external merge sort. Run formation: read about 4 GB at a time (less in practice, leaving room for overhead), sort it in memory and write it as a sorted run; 40 GB gives roughly 10 runs. Merge: open every run with a buffered reader and keep a min-heap holding each run's current record; repeatedly pop the smallest, write it out and push the next record from the same run. With R runs the heap has R entries, so each record costs O(log R) comparisons, O(N log R) for N records, plus O(N log(N/R)) for the in-memory sorts, O(N log N) overall. I/O is usually the bottleneck: run formation reads and writes every byte once and a single merge pass reads and writes it once more. A single merge pass needs one input buffer per run plus an output buffer in memory; with too many runs (thousands), merge in rounds with fan-in k, needing about ceil(log base k of R) merge passes (a standard estimate; check boundary cases). Larger runs mean fewer runs, but memory spent on run size competes with memory for merge buffers. Large sequential reads matter more than comparison counts. To keep file order for equal timestamps, break ties by run index, assuming each run was sorted with a stable sort. Handle records split across read boundaries, a crash midway (write temporary files and rename the finished output) and cleanup. A heap-based merge matched Array.sort on 2,000 random small cases in a simulation. Alternatives: partition by time range into files that each fit in memory, or use a tool that already implements this, such as a database or the sort command. Test an empty file, a single run, equal keys, a record larger than a buffer and a truncated final line."),
  ask("unfamiliar-codebase-fix", "BEHAVIORAL", "EASY", "design", "Fixing a Bug in Code You Did Not Write", "Tell me about a time you had to fix a bug or add a small feature in a codebase you did not write and did not yet understand. How did you learn enough to change it safely, who did you ask and when, and how did you check that you had not broken anything? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer names the situation and the pressure, then shows a method rather than luck: reproducing the problem first, tracing from the entry point to the behavior with search, a debugger or temporary logging, reading the existing tests, and checking the history for why the code looks the way it does. It shows that you asked a targeted question after investigating, saying what you had already tried, and that you kept the change as small as the problem allowed. It describes how you verified the result: running the existing tests, adding a regression test, and asking for review from someone who knows the area. Close with the outcome stated honestly and one thing you left better for the next person, such as a note or a test. Avoid answers that skip the learning process or claim you understood everything."),
  ask("safe-refactor", "BEHAVIORAL", "EASY", "design", "Cleaning Up Code Without Changing Behavior", "Describe a time you restructured existing code, such as renaming things, splitting a long function or removing duplication, without changing what it did. How did you make sure the behavior stayed the same, how did you keep the change easy to review, and how did you decide when to stop? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer starts with why the cleanup was worth doing now (it was in the way of a task, or a source of mistakes) and how you protected behavior: running the existing tests before and after, or writing tests that pin down the current behavior first when none existed, then working in small steps with the tests passing after each. It keeps refactoring commits separate from behavior changes so reviewers can check each kind, uses tool-assisted renames and the type checker where available, and keeps the change small enough to review. It explains the stopping rule, such as finishing the part the task needed and recording the rest as follow-up work rather than rewriting everything. Be honest about anything that slipped through or was caught late. Avoid claiming a large rewrite was risk-free or that no testing was needed."),
  ask("reviewing-risky-change", "BEHAVIORAL", "MEDIUM", "design", "Reviewing a Large or Risky Change", "Describe a time you reviewed a teammate's pull request that was large or that you thought had a problem. How did you decide what to look at first, how did you word your comments, and what happened afterwards? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer shows triage: reading the description and the tests first, then looking at the riskiest parts (authorization, data changes, concurrency, migrations, error handling) and running or exercising the change when reading was not enough. It shows you asked for a large change to be split rather than skimming it, and that you separated blocking problems from preferences. Comments are specific and explain the reason, suggest an alternative or ask a question instead of making a judgment about the person, and acknowledge what was done well. If a written thread grew long, you moved to a call or pairing and recorded the outcome. Describe the result and what the experience taught you about your own pull requests. Avoid answers that describe approving without reading or nitpicking only style."),
  ask("flaky-tests", "BEHAVIORAL", "MEDIUM", "design", "Taking On a Recurring Annoyance", "Tell me about a time something small but recurring slowed your team down, such as a test that failed one run in five. How did you decide it was worth your time, how did you investigate, and how did you get others to adopt the fix? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer sizes the cost with whatever evidence you actually had (how often it happened, how much time each occurrence took) and timeboxes the effort against assigned work rather than ignoring it. It shows methodical investigation: collecting failing logs, reproducing by repetition or a fixed random seed, then looking for shared state, order dependence, real clocks, sleeps, network calls or resource limits. It distinguishes fixing the root cause from a temporary quarantine, and a quarantine has an owner and an expiry. It explains how you told the team, got review and agreement, and checked afterwards that the failure rate really dropped. Quantify only what you can support. Avoid presenting a workaround such as retrying until green as a fix, or neglecting your committed work."),
  ask("conflicting-stakeholders", "BEHAVIORAL", "HARD", "design", "Two Stakeholders, One Roadmap Slot", "Tell me about a time two people with a say in your work wanted incompatible things, for example two managers, or a customer-facing team and an internal team. How did you find out what each of them actually needed, how did you bring the conflict into the open, and what was decided? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer shows you did not quietly choose a side or promise both. You asked each person about the goal and constraint behind the request, as opposed to the proposed solution, and made the tradeoffs concrete: what each option costs, what it delays, and what capacity exists. You brought the parties together, or went to the person who owns prioritization, with options such as a smaller version of each, phasing, or deferral with a date, and you recorded the decision and its reasoning. You followed up with whoever did not get what they asked for, so they understood why and what comes next. State the outcome honestly, including costs. Avoid portraying either stakeholder as unreasonable, or describing a solution that depended on your personal persuasion rather than a shared decision."),
  ask("cross-team-migration", "BEHAVIORAL", "HARD", "design", "Leading a Change Across Other Teams", "Describe a time you drove a change that required other teams to do work, such as migrating off a deprecated library or adopting a new process, when you had no authority to assign that work. How did you make the case, reduce the effort for others, track progress, and handle teams that did not move? Use a real experience if you have one; otherwise clearly label a hypothetical response.", "A strong answer opens with a clear problem statement and a reason for the deadline (risk, cost, an end-of-support date), backed by evidence. It shows you made adoption cheap: a migration guide, a script or codemod, a pilot you did yourself first, and office hours. It describes visible tracking, such as a list of teams with owners and status, a fixed definition of done, and agreeing dates around each team's own priorities. For teams that did not move, it shows offering help, understanding their blockers and escalating with data when needed, not blame. It ends with removing the old path, the measured result, and honest credit to the teams that did the work. Avoid claiming sole credit, or describing success that depended on authority you did not have."),
  ask("observe-small-app", "SYSTEM_DESIGN", "EASY", "system-design", "Seeing Inside a Small Web App", "A web app runs on one server with one database and has no monitoring: the team learns about outages from users. Design the minimum logging, metrics, health checks and alerts that would let you detect an outage within minutes and diagnose it. Explain what you record, what you must keep out of the logs, which alerts you set first and how you avoid noisy alerts.", "Logs: write structured entries (for example JSON) with a timestamp, level, request id that follows the request through the code, route, status and duration, shipped off the server so they survive a restart and kept for a limited retention period. Keep out passwords, tokens, session ids, secrets and full personal or payment data. Metrics: request rate, error rate (5xx) and latency percentiles per route, plus saturation signals such as CPU, memory, disk and database connections. Health checks: a liveness check (the process is up) separate from a readiness check (it can reach the database), and an external probe from outside your network to catch DNS, certificate and network failures; be careful that a failing readiness check does not cause restart loops. Alerts, symptom-first: error rate above a threshold for several minutes, p95 latency over target, the external probe failing, disk nearly full, and backups failing. Give each alert an owner and a one-line runbook, require the condition to persist for a window to avoid flapping, page only for user-visible impact and send the rest to a ticket queue. Mark deploys on dashboards so changes can be correlated with errors. Avoid labeling metrics with unbounded values such as user ids. Test with drills: stop the database and confirm the readiness check and the alert fire, then throw a deliberate error and find it by request id."),
  ask("recipe-schema", "SYSTEM_DESIGN", "EASY", "sql", "A Recipe Box Schema", "Design the tables for a recipe app. Recipes have a title and a number of servings; each recipe uses several ingredients with a quantity and unit; the same ingredient appears in many recipes; recipes can have tags such as 'vegan'. Give the tables and keys, say how you prevent duplicate or nonsensical rows, and write a query for recipes that use both flour and eggs.", "Many-to-many relationships need join tables. Tables: recipes (id, title, servings CHECK (servings > 0)); ingredients (id, name UNIQUE); recipe_ingredients (recipe_id, ingredient_id, quantity CHECK (quantity > 0), unit, PRIMARY KEY (recipe_id, ingredient_id)) with foreign keys to both parents; tags (id, name UNIQUE); recipe_tags (recipe_id, tag_id, PRIMARY KEY (recipe_id, tag_id)). Add an index on recipe_ingredients (ingredient_id) for lookups by ingredient; the primary key already serves lookups by recipe. Keeping ingredient names in one table avoids misspelled copies and lets a rename change one row; quantity and unit belong to the relationship, not to the ingredient. In a PostgreSQL 17 run these constraints rejected a duplicate ingredient within a recipe, a zero quantity and deletion of an ingredient still in use, and deleting a recipe removed its lines when the foreign key used ON DELETE CASCADE. A plain UNIQUE on name still allows 'Flour' beside 'flour', so normalize names or add a unique index on lower(name). Query: SELECT r.id, r.title FROM recipes r JOIN recipe_ingredients ri ON ri.recipe_id = r.id JOIN ingredients i ON i.id = ri.ingredient_id WHERE i.name IN ('flour', 'eggs') GROUP BY r.id, r.title HAVING COUNT(DISTINCT i.id) = 2; the HAVING count must equal the number of names requested, so a recipe with only one of them is excluded. Scaling servings is quantity * wanted / servings; mixing units such as grams and cups needs conversion rules. Test a recipe with only one of the two ingredients, an unknown ingredient name and deleting a recipe that has tags."),
  ask("api-evolution", "SYSTEM_DESIGN", "MEDIUM", "system-design", "Changing an API Without Breaking Old Apps", "A mobile app calls GET /v1/orders and reads a field called total as an integer number of cents. The backend team wants to rename it to amountCents, add a required field to order creation, and replace the status value PENDING with two values, PAYMENT_PENDING and SHIPPING_PENDING. Many users run app versions that are months old. Design the rollout so existing clients keep working, and explain how you will know when the old behavior can be removed.", "Classify the changes. Renaming or removing a response field, making a request field required, and changing enum values are breaking changes; adding an optional response field, or an optional request field with a server default, is usually compatible if clients ignore unknown fields, which you must verify for your own clients because some strict parsers fail on unknown fields or unknown enum values. Plan: go additive first by returning both total and amountCents with the same value during a transition; accept the new field as optional with a documented default for old clients; for status, keep the meaning of PENDING for old clients by translating the new states back to PENDING at the API boundary, or expose the new values only to clients that opt in by version, header or minimum app build. Keep business logic shared and translate at the edge, and keep the number of live versions small. For data changes use expand then contract: add the new column, backfill, write both, switch reads, drop the old one later. Deprecation: announce it, add a deprecation signal to responses and docs, record usage by app build to measure how much traffic still uses the old behavior, nudge or force old builds to upgrade, and remove only after an agreed date and threshold. Run recorded requests from old client versions against the new server as contract tests in CI, and roll out behind a flag or canary with the ability to roll back. Remember that offline queues and caches can deliver old-format requests late. Test old-client fixtures, an unknown enum value, a missing optional field and mixed versions."),
  ask("login-sessions", "SYSTEM_DESIGN", "MEDIUM", "system-design", "Login Sessions for a Web App", "Design how a web app keeps users logged in after they enter a password. Compare server-side sessions with signed self-contained tokens such as JWTs, explain where the credential is stored in the browser and why, and describe logout, 'log out of all devices', and what happens when a user's role changes or an account is disabled.", "Server-side sessions: after login the server creates a long random session id from a secure random source, stores it with the user id and an expiry in a database or fast store, and gives the browser only the id in a cookie. Logout deletes the record, 'log out of all devices' deletes every record for the user, and a role change or disabled account takes effect on the next request because the server reads current state; the cost is a lookup per request and a shared store when there are several servers. Signed tokens carry claims (user id, roles, expiry) that any server can verify without a lookup, but they stay valid until they expire, so revocation, role changes and disabling lag unless you add a denylist or a per-user version number (which brings back state) or use short-lived access tokens with a revocable refresh token stored on the server. The payload is readable by anyone holding the token, so signing is not encryption and secrets do not belong in it; verify with the algorithm you expect rather than one the token names. Cookie attributes: HttpOnly keeps page scripts from reading the cookie, which limits theft after a script injection; Secure sends it only over HTTPS; SameSite (Lax or Strict) limits cross-site sending and complements, but does not replace, CSRF defenses on state-changing requests. A token kept in localStorage is readable by any script on the page. Also issue a new session id at login to prevent fixation, set idle and absolute timeouts, rate-limit logins, ask for the password again before sensitive actions, and log security events. Test using an old cookie after logout, after a password change and after role removal, a tampered token, an expired token and a pre-login session id reused after login."),
  ask("backup-recovery", "SYSTEM_DESIGN", "HARD", "system-design", "Backups You Can Actually Restore", "A small SaaS keeps all customer data in one PostgreSQL database. Management wants to lose at most 15 minutes of data and be serving again within two hours after the database is lost or corrupted. Design the backup and recovery approach, explain how you verify it works, and describe failures that backups alone do not cover, such as an accidental delete that replicates.", "Name the targets: the recovery point objective (RPO) is how much data you may lose, here 15 minutes, and the recovery time objective (RTO) is how long recovery may take, here two hours. Use periodic base backups plus continuous archiving of the write-ahead log, which allows point-in-time recovery to a chosen moment in PostgreSQL; a nightly backup alone could lose up to a day and misses the 15-minute goal. Alert when archive lag approaches the RPO. A streaming replica helps with server failure by allowing fast failover, but it replays deletes and corruption immediately, so it is not a backup. Store backups outside the primary's failure domain (another account or region), encrypted and access-controlled, with retention and delete protection so a compromised credential or ransomware cannot erase them. Verify by restoring regularly into a scratch environment, checking row counts or a known canary record, running an application smoke test, and recording the elapsed time against the two-hour target; restore time grows with data size, so measure again as it grows. Alert on missing or failed backups, and have someone who did not write the runbook rehearse it, including restoring to just before a bad deploy or accidental DELETE and copying selected rows back. Gaps that backups do not close: accidental or malicious deletes need point-in-time recovery plus quick detection; a bad migration; lost encryption keys or credentials for the backup store, which should be recoverable separately; a provider account lockout; and state outside the database such as object storage, queues, third-party services and secrets. Decide who may declare a recovery, the order in which services come back, and how users are told. Test restoring to a specific time, restoring when the newest backup is missing and the real elapsed time."),
  ask("tenant-isolation", "SYSTEM_DESIGN", "HARD", "system-design", "Keeping Customers' Data Apart", "A B2B SaaS app serves thousands of companies (tenants) from one PostgreSQL database. A single missing WHERE tenant_id = ? in any query could expose one customer's data to another. Compare isolation approaches, design the schema and database settings you would use to make that mistake hard, and explain what each approach does not protect against.", "Options: a database per tenant (strongest isolation, per-tenant restore and resource control, but thousands of databases mean heavy operations and every migration repeated); a schema per tenant (a middle path with many objects and migration fan-out); or shared tables with a tenant_id column (cheapest and scales to many small tenants, but isolation depends on discipline unless the database enforces it). For shared tables, make tenant_id NOT NULL on every tenant-owned table and part of its keys, and use composite foreign keys such as FOREIGN KEY (tenant_id, customer_id) REFERENCES customers (tenant_id, id), so a child row cannot point at another tenant's parent. In a PostgreSQL 17 check, a single-column foreign key let a tenant 2 row reference a tenant 1 row even with row-level security enabled, because the referential check is not subject to the policies, while the composite key rejected it. Add row-level security: ALTER TABLE ... ENABLE ROW LEVEL SECURITY and CREATE POLICY ... USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::bigint). Set the value per request with set_config('app.tenant_id', $1, true) inside a transaction so it is local to that transaction; with pooled connections a session-level setting can leak to the next request. In the check the value was empty after commit and a session with no value saw zero rows, so it failed closed, and a policy with only USING also rejected inserts for another tenant. Superusers and roles with BYPASSRLS skip policies, and a table owner skips them unless the table has FORCE ROW LEVEL SECURITY, so connect the application as a separate role that owns nothing and has no bypass, and run migrations and admin jobs as another role. Also lead indexes with tenant_id, apply per-tenant quotas and rate limits against noisy neighbors, and remember that policies cover only those tables: caches, search indexes, object storage keys, logs and exports need tenant scoping too, and row-level security does not replace authorization inside a tenant. Backups cover all tenants together, so restoring one tenant needs extra tooling. Test with two tenants and every endpoint using the other's ids, run queries as the application role with no tenant set, and check that new tables have tenant_id and a policy."),
];
